// Shared types used across the entire DevGuard backend

export type SessionStatus =
  | 'idle'
  | 'ingesting'
  | 'analyzing'
  | 'running_tests'
  | 'generating_report'
  | 'complete'
  | 'error';

export interface Session {
  id: string;
  status: SessionStatus;
  repoPath: string;
  repoUrl?: string;
  createdAt: string;
  updatedAt: string;
  error?: string;
  progress?: Progress;
  result?: AnalysisResult;
}

export interface Progress {
  step: string;
  detail?: string;
  percent?: number;
}

// ─── Repository Understanding ────────────────────────────────────────────────

export interface RepoMetadata {
  name: string;
  description?: string;
  language: 'typescript' | 'javascript' | 'mixed' | 'unknown';
  framework?: string;
  packageManager: 'npm' | 'yarn' | 'pnpm' | 'unknown';
  hasTests: boolean;
  testFrameworks: string[];
  entryPoints: string[];
  fileCount: number;
  sourceFileCount: number;
  testFileCount: number;
  dependencies: Record<string, string>;
  devDependencies: Record<string, string>;
  scripts: Record<string, string>;
  gitRemote?: string;
  lastCommit?: string;
}

// ─── Test Analysis ───────────────────────────────────────────────────────────

export type TestGapSeverity = 'critical' | 'high' | 'medium' | 'low';
export type TestGapCategory =
  | 'uncovered_function'
  | 'uncovered_class'
  | 'uncovered_api_route'
  | 'uncovered_error_path'
  | 'uncovered_edge_case'
  | 'missing_integration_test';

export interface TestGap {
  id: string;
  severity: TestGapSeverity;
  category: TestGapCategory;
  title: string;
  description: string;
  filePath: string;
  symbolName?: string;
  lineStart?: number;
  lineEnd?: number;
  suggestedTestTitle?: string;
  rationale: string;
}

export interface TestFile {
  path: string;
  framework: string;
  testCount: number;
  describedFunctions: string[];
}

export interface TestAnalysis {
  totalSourceFiles: number;
  totalTestFiles: number;
  estimatedCoveragePercent: number;
  testFiles: TestFile[];
  gaps: TestGap[];
  untestedFiles: string[];
  untestedApiRoutes: RouteInfo[];
  summary: string;
}

export interface RouteInfo {
  method: string;
  path: string;
  filePath: string;
  handler?: string;
  line?: number;
}

// ─── Configuration Analysis ──────────────────────────────────────────────────

export type ConfigIssueSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';
export type ConfigIssueCategory =
  | 'missing_env_var'
  | 'undocumented_env_var'
  | 'secret_in_code'
  | 'port_mismatch'
  | 'docker_inconsistency'
  | 'ci_inconsistency'
  | 'missing_config_file'
  | 'dependency_version_mismatch'
  | 'node_version_mismatch'
  | 'script_inconsistency'
  | 'readme_inconsistency';

export interface ConfigIssue {
  id: string;
  severity: ConfigIssueSeverity;
  category: ConfigIssueCategory;
  title: string;
  description: string;
  filePath?: string;
  line?: number;
  recommendation: string;
  affectedFiles?: string[];
}

export interface EnvVarInfo {
  name: string;
  definedIn: string[];
  usedIn: string[];
  hasDefault: boolean;
  isSecret: boolean;
}

export interface ConfigAnalysis {
  issues: ConfigIssue[];
  envVars: EnvVarInfo[];
  dockerfiles: string[];
  ciFiles: string[];
  hasEnvExample: boolean;
  hasDotenv: boolean;
  portMentions: PortMention[];
  summary: string;
}

export interface PortMention {
  port: number;
  filePath: string;
  context: string;
  line?: number;
}

// ─── Risk & Recommendations ───────────────────────────────────────────────────

export type RiskLevel = 'critical' | 'high' | 'medium' | 'low';

export interface Risk {
  id: string;
  level: RiskLevel;
  title: string;
  description: string;
  category: 'testing' | 'configuration' | 'security' | 'reliability';
  sourceGapIds?: string[];
  sourceIssueIds?: string[];
  recommendation: string;
  estimatedImpact: string;
}

// ─── Test Execution ───────────────────────────────────────────────────────────

export type TestRunStatus = 'pending' | 'running' | 'passed' | 'failed' | 'skipped' | 'error';

export interface TestRunResult {
  status: TestRunStatus;
  passed: number;
  failed: number;
  skipped: number;
  total: number;
  duration?: number;
  output: string;
  failedTests: FailedTest[];
}

export interface FailedTest {
  name: string;
  error: string;
  file?: string;
}

export interface GeneratedTest {
  filePath: string;
  content: string;
  targetFile: string;
  targetSymbol?: string;
  framework: string;
}

// ─── Final Report ────────────────────────────────────────────────────────────

export interface AnalysisResult {
  sessionId: string;
  repoMetadata: RepoMetadata;
  testAnalysis: TestAnalysis;
  configAnalysis: ConfigAnalysis;
  risks: Risk[];
  testRunResult?: TestRunResult;
  generatedTests?: GeneratedTest[];
  healthScore: HealthScore;
  completedAt: string;
}

export interface HealthScore {
  overall: number;       // 0-100
  testing: number;       // 0-100
  configuration: number; // 0-100
  security: number;      // 0-100
  grade: 'A' | 'B' | 'C' | 'D' | 'F';
}

// ─── API Request/Response ────────────────────────────────────────────────────

export interface StartAnalysisRequest {
  repoPath?: string;
  repoUrl?: string;
}

export interface ApiError {
  error: string;
  detail?: string;
}

