import { Router, Request, Response } from 'express';
import path from 'path';
import fs from 'fs';
import { z } from 'zod';
import {
  createSession,
  getSession,
  updateSessionStatus,
  setSessionError,
  setSessionResult,
} from '../store/sessionStore';
import { runFullAnalysis } from '../analysis/pipeline';

export const analysisRouter = Router();

const startSchema = z.object({
  repoPath: z.string().optional(),
  repoUrl: z.string().url().optional(),
}).refine(data => data.repoPath ?? data.repoUrl, {
  message: 'Either repoPath or repoUrl is required',
});

analysisRouter.post('/start', async (req: Request, res: Response) => {
  const parsed = startSchema.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: 'Invalid request', detail: parsed.error.message });
    return;
  }

  const { repoPath, repoUrl } = parsed.data;

  // Resolve the local path
  let resolvedPath: string;
  if (repoPath) {
    resolvedPath = path.resolve(repoPath);
    if (!fs.existsSync(resolvedPath)) {
      res.status(400).json({ error: 'Repository path does not exist', detail: resolvedPath });
      return;
    }
  } else {
    // For remote URLs, we'll clone to a temp dir during analysis
    resolvedPath = '';
  }

  const session = createSession(resolvedPath, repoUrl);
  res.status(202).json({ sessionId: session.id });

  // Run analysis in the background — do not await
  runFullAnalysis(session.id, resolvedPath, repoUrl).catch((err: unknown) => {
    const message = err instanceof Error ? err.message : String(err);
    setSessionError(session.id, message);
  });
});

analysisRouter.get('/:sessionId/status', (req: Request, res: Response) => {
  const session = getSession(req.params.sessionId);
  if (!session) {
    res.status(404).json({ error: 'Session not found' });
    return;
  }
  res.json({
    id: session.id,
    status: session.status,
    progress: session.progress,
    error: session.error,
    createdAt: session.createdAt,
    updatedAt: session.updatedAt,
  });
});

analysisRouter.get('/:sessionId/result', (req: Request, res: Response) => {
  const session = getSession(req.params.sessionId);
  if (!session) {
    res.status(404).json({ error: 'Session not found' });
    return;
  }
  if (session.status !== 'complete') {
    res.status(409).json({ error: 'Analysis not yet complete', status: session.status });
    return;
  }
  res.json(session.result);
});

