export type SessionStatus =
  | 'idle'
  | 'ingesting'
  | 'analyzing_repo'
  | 'analyzing_tests'
  | 'analyzing_config'
  | 'scoring'
  | 'generating_tests'
  | 'running_tests'
  | 'complete'
  | 'error';

export interface Session {
  id: string;
  status: SessionStatus;
  repoPath: string;
  repoUrl?: string;
  createdAt: string;
  updatedAt: string;
  error?: string;
  progress?: Progress;
  result?: AnalysisResult;
}

export interface Progress {
  step: string;
  detail?: string;
  percent: number;
}

// ─── Repository ───────────────────────────────────────────────────────────────

export type Language = 'typescript' | 'javascript' | 'mixed' | 'unknown';
export type PackageManager = 'npm' | 'yarn' | 'pnpm' | 'unknown';

