import { v4 as uuidv4 } from 'uuid';
import type { Session, SessionStatus, Progress, AnalysisResult } from '../types';

const sessions = new Map<string, Session>();

export function createSession(repoPath: string, repoUrl?: string): Session {
  const session: Session = {
    id: uuidv4(),
    status: 'idle',
    repoPath,
    repoUrl,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  sessions.set(session.id, session);
  return session;
}

export function getSession(id: string): Session | undefined {
  return sessions.get(id);
}

export function listSessions(): Session[] {
  return Array.from(sessions.values()).sort(
    (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );
}

export function updateSessionProgress(
  id: string,
  status: SessionStatus,
  progress: Progress
): void {
  const s = sessions.get(id);
  if (!s) return;
  s.status = status;
  s.progress = progress;
  s.updatedAt = new Date().toISOString();
}

export function setSessionError(id: string, error: string): void {
  const s = sessions.get(id);
  if (!s) return;
  s.status = 'error';
  s.error = error;
  s.progress = undefined;
  s.updatedAt = new Date().toISOString();
}

export function setSessionResult(id: string, result: AnalysisResult): void {
  const s = sessions.get(id);
  if (!s) return;
  s.status = 'complete';
  s.result = result;
  s.progress = undefined;
  s.updatedAt = new Date().toISOString();
}

export function deleteSession(id: string): boolean {
  return sessions.delete(id);
}

