// Frontend-local types mirroring the backend shape.
// Keep in sync with backend/src/types/index.ts

export type SessionStatus =
  | 'idle'
  | 'ingesting'
  | 'analyzing_repo'
  | 'analyzing_tests'
  | 'analyzing_config'
  | 'scoring'
  | 'generating_tests'
  | 'running_tests'
  | 'complete'
  | 'error';

export interface Progress {
  step: string;
  detail?: string;
  percent: number;
}

export interface SessionPoll {
  id: string;
  status: SessionStatus;
  progress?: Progress;
  error?: string;
  createdAt: string;
  updatedAt: string;
}

// ─── Repository ───────────────────────────────────────────────────────────────

export type Language = 'typescript' | 'javascript' | 'mixed' | 'unknown';
export type PackageManager = 'npm' | 'yarn' | 'pnpm' | 'unknown';

export interface RepoMetadata {
  name: string;
  description?: string;
  language: Language;
  framework?: string;
  packageManager: PackageManager;
  hasTests: boolean;
  testFrameworks: string[];
  entryPoints: string[];
  fileCount: number;
  sourceFileCount: number;
  testFileCount: number;
  dependencies: Record<string, string>;
  devDependencies: Record<string, string>;
  scripts: Record<string, string>;
  nodeVersion?: string;
  gitRemote?: string;
  lastCommit?: string;
  isMonorepo: boolean;
  workspaces: string[];
}

// ─── Test Analysis ───────────────────────────────────────────────────────────

export type GapSeverity = 'critical' | 'high' | 'medium' | 'low';
export type GapCategory =
  | 'uncovered_function'
  | 'uncovered_class'
  | 'uncovered_api_route'
  | 'uncovered_error_path'
  | 'uncovered_edge_case'
  | 'missing_integration_test'
  | 'missing_auth_test';

export interface TestGap {
  id: string;
  severity: GapSeverity;
  category: GapCategory;
  title: string;
  description: string;
  filePath: string;
  symbolName?: string;
  lineStart?: number;
  lineEnd?: number;
  suggestedTestTitle?: string;
  rationale: string;
}

export interface TestFile {
  path: string;
  framework: string;
  testCount: number;
  coveredSymbols: string[];
}

export interface RouteInfo {
  method: string;
  path: string;
  filePath: string;
  handlerName?: string;
  line?: number;
  hasCoverage: boolean;
}

export interface TestAnalysis {
  totalSourceFiles: number;
  totalTestFiles: number;
  estimatedCoveragePercent: number;
  testFiles: TestFile[];
  gaps: TestGap[];
  untestedFiles: string[];
  apiRoutes: RouteInfo[];
  untestedApiRoutes: RouteInfo[];
  summary: string;
}

// ─── Config Analysis ─────────────────────────────────────────────────────────

export type IssueSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';
export type IssueCategory =
  | 'missing_env_var'
  | 'undocumented_env_var'
  | 'secret_in_code'
  | 'port_mismatch'
  | 'docker_inconsistency'
  | 'ci_inconsistency'
  | 'missing_config_file'
  | 'dependency_version_mismatch'
  | 'node_version_mismatch'
  | 'script_inconsistency'
  | 'readme_inconsistency';

export interface ConfigIssue {
  id: string;
  severity: IssueSeverity;
  category: IssueCategory;
  title: string;
  description: string;
  filePath?: string;
  line?: number;
  recommendation: string;
  affectedFiles?: string[];
}

export interface EnvVarInfo {
  name: string;
  definedIn: string[];
  usedIn: string[];
  hasDefault: boolean;
  isSecret: boolean;
}

export interface PortMention {
  port: number;
  filePath: string;
  context: string;
  line?: number;
}

export interface ConfigAnalysis {
  issues: ConfigIssue[];
  envVars: EnvVarInfo[];
  dockerfiles: string[];
  ciFiles: string[];
  hasEnvExample: boolean;
  hasDotenv: boolean;
  portMentions: PortMention[];
  summary: string;
}

// ─── Risk & Health ────────────────────────────────────────────────────────────

export type RiskLevel = 'critical' | 'high' | 'medium' | 'low';

export interface Risk {
  id: string;
  level: RiskLevel;
  title: string;
  description: string;
  category: 'testing' | 'configuration' | 'security' | 'reliability';
  sourceGapIds: string[];
  sourceIssueIds: string[];
  recommendation: string;
  estimatedImpact: string;
}

export interface HealthScore {
  overall: number;
  testing: number;
  configuration: number;
  security: number;
  grade: 'A' | 'B' | 'C' | 'D' | 'F';
}

// ─── Test Execution ───────────────────────────────────────────────────────────

export type TestRunStatus = 'pending' | 'running' | 'passed' | 'failed' | 'error' | 'skipped';

export interface FailedTest {
  name: string;
  error: string;
  file?: string;
}

export interface TestRunResult {
  status: TestRunStatus;
  passed: number;
  failed: number;
  skipped: number;
  total: number;
  duration?: number;
  output: string;
  failedTests: FailedTest[];
}

export interface GeneratedTest {
  filePath: string;
  content: string;
  targetFile: string;
  targetSymbol?: string;
  framework: string;
  gapId: string;
}

// ─── Analysis Result ──────────────────────────────────────────────────────────

export interface AnalysisResult {
  sessionId: string;
  repoMetadata: RepoMetadata;
  testAnalysis: TestAnalysis;
  configAnalysis: ConfigAnalysis;
  risks: Risk[];
  healthScore: HealthScore;
  generatedTests: GeneratedTest[];
  testRunResult?: TestRunResult;
  completedAt: string;
}

// ─── UI State ─────────────────────────────────────────────────────────────────

export type ActiveTab = 'overview' | 'testing' | 'configuration' | 'validation' | 'report';

export interface AppState {
  activeTab: ActiveTab;
  sessionId: string | null;
  sessionStatus: SessionStatus;
  progress: Progress | null;
  result: AnalysisResult | null;
  error: string | null;
}

