import type { GapSeverity, IssueSeverity, RiskLevel, HealthScore } from '../types';

/** Human-readable label for a test gap category key */
export const GAP_CATEGORY_LABELS: Record<string, string> = {
  uncovered_function: 'Uncovered Function',
  uncovered_class: 'Uncovered Class',
  uncovered_api_route: 'API Route Not Tested',
  uncovered_error_path: 'Error Path Missing',
  uncovered_edge_case: 'Edge Case Missing',
  missing_integration_test: 'Integration Test Missing',
  missing_auth_test: 'Auth Test Missing',
};

/** Human-readable label for a config issue category */
export const ISSUE_CATEGORY_LABELS: Record<string, string> = {
  missing_env_var: 'Missing Env Var',
  undocumented_env_var: 'Undocumented Env Var',
  secret_in_code: 'Secret in Code',
  port_mismatch: 'Port Mismatch',
  docker_inconsistency: 'Docker Inconsistency',
  ci_inconsistency: 'CI Inconsistency',
  missing_config_file: 'Missing Config File',
  dependency_version_mismatch: 'Version Mismatch',
  node_version_mismatch: 'Node Version Mismatch',
  script_inconsistency: 'Script Inconsistency',
  readme_inconsistency: 'README Inconsistency',
};

export function severityColor(s: GapSeverity | IssueSeverity | RiskLevel): string {
  switch (s) {
    case 'critical': return 'text-red-400';
    case 'high':     return 'text-orange-400';
    case 'medium':   return 'text-yellow-400';
    case 'low':      return 'text-gray-400';
    case 'info':     return 'text-blue-400';
    default:         return 'text-gray-400';
  }
}

export function severityBadgeClass(s: GapSeverity | IssueSeverity | RiskLevel): string {
  switch (s) {
    case 'critical': return 'badge-critical';
    case 'high':     return 'badge-high';
    case 'medium':   return 'badge-medium';
    case 'low':      return 'badge-low';
    case 'info':     return 'badge-info';
    default:         return 'badge-low';
  }
}

export function severityBorderClass(s: GapSeverity | IssueSeverity | RiskLevel): string {
  switch (s) {
    case 'critical': return 'border-l-red-500';
    case 'high':     return 'border-l-orange-500';
    case 'medium':   return 'border-l-yellow-500';
    case 'low':      return 'border-l-gray-600';
    case 'info':     return 'border-l-blue-500';
    default:         return 'border-l-gray-600';
  }
}

export function gradeColor(grade: HealthScore['grade']): string {
  switch (grade) {
    case 'A': return 'text-green-400';
    case 'B': return 'text-blue-400';
    case 'C': return 'text-yellow-400';
    case 'D': return 'text-orange-400';
    case 'F': return 'text-red-400';
  }
}

export function scoreBarColor(score: number): string {
  if (score >= 80) return 'bg-green-500';
  if (score >= 60) return 'bg-blue-500';
  if (score >= 40) return 'bg-yellow-500';
  if (score >= 20) return 'bg-orange-500';
  return 'bg-red-500';
}

/** Truncate a file path for display, keeping the last N segments */
export function shortPath(p: string, segments = 3): string {
  const parts = p.replace(/\\/g, '/').split('/').filter(Boolean);
  if (parts.length <= segments) return p;
  return '…/' + parts.slice(-segments).join('/');
}

/** Format milliseconds as a human-readable duration */
export function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`;
  return `${Math.floor(ms / 60_000)}m ${Math.floor((ms % 60_000) / 1000)}s`;
}

