const BASE = '/api';

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    ...options,
  });
  const body = await res.json();
  if (!res.ok) {
    throw new Error(body.detail ?? body.error ?? `HTTP ${res.status}`);
  }
  return body as T;
}

export interface StartAnalysisRequest {
  repoPath?: string;
  repoUrl?: string;
  runTests?: boolean;
  generateTests?: boolean;
}

export interface StartAnalysisResponse {
  sessionId: string;
}

export interface SessionStatus {
  id: string;
  status: string;
  progress?: { step: string; detail?: string; percent: number };
  error?: string;
  createdAt: string;
  updatedAt: string;
}

export const api = {
  health: () => request<{ status: string; service: string; version: string }>('/health'),

  startAnalysis: (body: StartAnalysisRequest) =>
    request<StartAnalysisResponse>('/analysis/start', {
      method: 'POST',
      body: JSON.stringify(body),
    }),

  getStatus: (sessionId: string) =>
    request<SessionStatus>(`/analysis/${sessionId}/status`),

  getResult: (sessionId: string) =>
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    request<any>(`/analysis/${sessionId}/result`),

  listSessions: () =>
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    request<any[]>('/sessions'),

  deleteSession: (sessionId: string) =>
    request<{ success: boolean }>(`/sessions/${sessionId}`, { method: 'DELETE' }),
};

