import { Shield } from 'lucide-react';
import type { ActiveTab } from '../types';

const TABS: { id: ActiveTab; label: string }[] = [
  { id: 'overview',       label: 'Overview' },
  { id: 'testing',        label: 'Testing' },
  { id: 'configuration',  label: 'Configuration' },
  { id: 'validation',     label: 'Validation' },
  { id: 'report',         label: 'Report' },
];

interface Props {
  activeTab: ActiveTab;
  onTabChange: (tab: ActiveTab) => void;
  hasResult: boolean;
}

export default function Header({ activeTab, onTabChange, hasResult }: Props) {
  return (
    <header className="border-b border-gray-800 bg-gray-950">
      <div className="max-w-screen-xl mx-auto px-6">
        {/* Top bar */}
        <div className="flex items-center justify-between h-14">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center flex-shrink-0">
              <Shield className="w-4.5 h-4.5 text-white" strokeWidth={2.5} />
            </div>
            <div className="flex items-baseline gap-2">
              <span className="text-white font-semibold text-base tracking-tight">DevGuard</span>
              <span className="text-gray-500 text-xs hidden sm:block">
                Repository Validation &amp; Health
              </span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-xs text-gray-600 font-mono">v0.1.0</span>
          </div>
        </div>

        {/* Nav tabs */}
        <nav className="flex gap-1 -mb-px">
          {TABS.map((tab) => {
            const isActive = tab.id === activeTab;
            const isDisabled = !hasResult && tab.id !== 'overview';
            return (
              <button
                key={tab.id}
                onClick={() => !isDisabled && onTabChange(tab.id)}
                disabled={isDisabled}
                className={[
                  'px-3.5 py-2.5 text-sm font-medium border-b-2 transition-colors',
                  isActive
                    ? 'border-blue-500 text-blue-400'
                    : isDisabled
                    ? 'border-transparent text-gray-700 cursor-not-allowed'
                    : 'border-transparent text-gray-400 hover:text-gray-200 hover:border-gray-600',
                ].join(' ')}
              >
                {tab.label}
              </button>
            );
          })}
        </nav>
      </div>
    </header>
  );
}

import { FolderOpen, Play, FlaskConical, Loader2, AlertCircle } from 'lucide-react';
import { useState } from 'react';

interface Props {
  onAnalyze: (repoPath: string, opts: { runTests: boolean; generateTests: boolean }) => void;
  onDemo: () => void;
  isLoading: boolean;
  error: string | null;
}

export default function RepoSelector({ onAnalyze, onDemo, isLoading, error }: Props) {
  const [repoPath, setRepoPath] = useState('');
  const [runTests, setRunTests] = useState(false);
  const [generateTests, setGenerateTests] = useState(true);

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!repoPath.trim()) return;
    onAnalyze(repoPath.trim(), { runTests, generateTests });
  }

  return (
    <div className="card">
      <div className="flex items-center gap-2 mb-4">
        <FolderOpen className="w-4 h-4 text-blue-400" />
        <span className="text-sm font-semibold text-gray-200">Repository</span>
      </div>

      <form onSubmit={handleSubmit} className="space-y-3">
        {/* Path input */}
        <div>
          <label className="block text-xs text-gray-500 mb-1.5 font-medium uppercase tracking-wide">
            Repository Path
          </label>
          <input
            type="text"
            value={repoPath}
            onChange={(e) => setRepoPath(e.target.value)}
            placeholder="/absolute/path/to/project"
            disabled={isLoading}
            className={[
              'w-full bg-gray-950 border rounded-lg px-3 py-2.5 text-sm font-mono text-gray-200',
              'placeholder-gray-600 focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500',
              'disabled:opacity-50 disabled:cursor-not-allowed',
              error ? 'border-red-700' : 'border-gray-700',
            ].join(' ')}
          />
        </div>

        {/* Options */}
        <div className="flex flex-wrap gap-4 pt-0.5">
          <label className="flex items-center gap-2 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={generateTests}
              onChange={(e) => setGenerateTests(e.target.checked)}
              disabled={isLoading}
              className="rounded border-gray-600 bg-gray-800 text-blue-500 focus:ring-blue-500 focus:ring-offset-gray-950"
            />
            <span className="text-xs text-gray-400">Generate test suggestions</span>
          </label>
          <label className="flex items-center gap-2 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={runTests}
              onChange={(e) => setRunTests(e.target.checked)}
              disabled={isLoading}
              className="rounded border-gray-600 bg-gray-800 text-blue-500 focus:ring-blue-500 focus:ring-offset-gray-950"
            />
            <span className="text-xs text-gray-400">Run existing tests</span>
          </label>
        </div>

        {/* Error */}
        {error && (
          <div className="flex items-start gap-2 p-3 rounded-lg bg-red-950 border border-red-800 text-sm text-red-300">
            <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {/* Actions */}
        <div className="flex items-center gap-2 pt-1">
          <button
            type="submit"
            disabled={isLoading || !repoPath.trim()}
            className="btn-primary"
          >
            {isLoading ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Play className="w-4 h-4" />
            )}
            {isLoading ? 'Analyzing…' : 'Analyze Repository'}
          </button>

          <button
            type="button"
            onClick={onDemo}
            disabled={isLoading}
            className="btn-secondary"
          >
            <FlaskConical className="w-4 h-4" />
            Try Demo Repository
          </button>
        </div>
      </form>
    </div>
  );
}

import { Loader2, CheckCircle2 } from 'lucide-react';
import type { Progress, SessionStatus } from '../types';

interface Props {
  status: SessionStatus;
  progress: Progress | null;
}

const STEP_LABELS: Partial<Record<SessionStatus, string>> = {
  ingesting:        'Loading repository…',
  analyzing_repo:   'Understanding repository structure…',
  analyzing_tests:  'Analyzing test coverage…',
  analyzing_config: 'Scanning configuration…',
  scoring:          'Calculating health score…',
  generating_tests: 'Generating test suggestions…',
  running_tests:    'Running tests…',
};

export default function AnalysisProgress({ status, progress }: Props) {
  if (status === 'idle' || status === 'complete' || status === 'error') return null;

  const label = progress?.step ?? STEP_LABELS[status] ?? 'Working…';
  const detail = progress?.detail;
  const percent = progress?.percent ?? 0;

  return (
    <div className="card space-y-3">
      <div className="flex items-center gap-2.5">
        <Loader2 className="w-4 h-4 text-blue-400 animate-spin flex-shrink-0" />
        <span className="text-sm font-medium text-gray-200">{label}</span>
        <span className="ml-auto text-xs text-gray-500 font-mono tabular-nums">{percent}%</span>
      </div>

      {/* Progress bar */}
      <div className="h-1.5 rounded-full bg-gray-800 overflow-hidden">
        <div
          className="h-full rounded-full bg-blue-500 transition-all duration-300"
          style={{ width: `${Math.min(percent, 100)}%` }}
        />
      </div>

      {detail && (
        <p className="text-xs text-gray-500 font-mono truncate">{detail}</p>
      )}

      {/* Step indicators */}
      <div className="flex items-center gap-1.5 pt-1 flex-wrap">
        {(
          [
            ['ingesting', 'Ingest'],
            ['analyzing_repo', 'Repo'],
            ['analyzing_tests', 'Tests'],
            ['analyzing_config', 'Config'],
            ['scoring', 'Score'],
          ] as [SessionStatus, string][]
        ).map(([step, label]) => {
          const stepOrder: SessionStatus[] = [
            'ingesting',
            'analyzing_repo',
            'analyzing_tests',
            'analyzing_config',
            'scoring',
            'generating_tests',
            'running_tests',
          ];
          const currentIdx = stepOrder.indexOf(status);
          const stepIdx = stepOrder.indexOf(step);
          const isDone = stepIdx < currentIdx;
          const isCurrent = stepIdx === currentIdx;

          return (
            <div key={step} className="flex items-center gap-1">
              <span
                className={[
                  'text-xs font-medium',
                  isDone    ? 'text-green-400' :
                  isCurrent ? 'text-blue-400' :
                              'text-gray-700',
                ].join(' ')}
              >
                {isDone ? <CheckCircle2 className="w-3 h-3 inline -mt-0.5" /> : null}
                {' '}{label}
              </span>
              {stepIdx < 4 && <span className="text-gray-800 text-xs">›</span>}
            </div>
          );
        })}
      </div>
    </div>
  );
}

