import { gradeColor, scoreBarColor } from '../lib/utils';
import type { HealthScore } from '../types';

interface Props {
  score: HealthScore;
}

interface ScoreRowProps {
  label: string;
  value: number;
}

function ScoreRow({ label, value }: ScoreRowProps) {
  return (
    <div className="space-y-1">
      <div className="flex justify-between items-center text-xs">
        <span className="text-gray-400">{label}</span>
        <span className="font-mono text-gray-300 tabular-nums">{value}/100</span>
      </div>
      <div className="h-1.5 rounded-full bg-gray-800 overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-500 ${scoreBarColor(value)}`}
          style={{ width: `${value}%` }}
        />
      </div>
    </div>
  );
}

export default function HealthScoreCard({ score }: Props) {
  return (
    <div className="card">
      <div className="flex items-start justify-between mb-5">
        <div>
          <p className="text-xs text-gray-500 uppercase tracking-wide font-medium mb-1">
            Health Score
          </p>
          <div className="flex items-baseline gap-2">
            <span className="text-5xl font-bold text-white tabular-nums">{score.overall}</span>
            <span className="text-gray-500 text-sm">/100</span>
          </div>
        </div>
        <div className={`text-5xl font-bold tabular-nums ${gradeColor(score.grade)}`}>
          {score.grade}
        </div>
      </div>

      {/* Ring-free score bars — cleaner than a chart for this data */}
      <div className="space-y-3">
        <ScoreRow label="Testing" value={score.testing} />
        <ScoreRow label="Configuration" value={score.configuration} />
        <ScoreRow label="Security" value={score.security} />
      </div>
    </div>
  );
}

import {
  GitBranch,
  FileCode2,
  FlaskConical,
  Package,
  Terminal,
  Globe,
} from 'lucide-react';
import type { RepoMetadata } from '../types';

interface Props {
  meta: RepoMetadata;
}

function Chip({ children }: { children: React.ReactNode }) {
  return (
    <span className="inline-flex items-center px-2 py-0.5 rounded bg-gray-800 border border-gray-700 text-xs text-gray-300 font-mono">
      {children}
    </span>
  );
}

function Row({ icon, label, children }: {
  icon: React.ReactNode;
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex items-start gap-3 py-2.5 border-b border-gray-800 last:border-0">
      <div className="w-4 h-4 mt-0.5 text-gray-500 flex-shrink-0">{icon}</div>
      <div className="flex-1 min-w-0">
        <p className="text-xs text-gray-500 mb-1">{label}</p>
        <div className="flex flex-wrap gap-1.5">{children}</div>
      </div>
    </div>
  );
}

export default function RepoOverviewCard({ meta }: Props) {
  const depCount = Object.keys(meta.dependencies).length;
  const devDepCount = Object.keys(meta.devDependencies).length;

  return (
    <div className="card">
      <div className="flex items-start justify-between mb-3">
        <div>
          <h2 className="text-base font-semibold text-white">{meta.name}</h2>
          {meta.description && (
            <p className="text-xs text-gray-400 mt-0.5">{meta.description}</p>
          )}
        </div>
        <Chip>{meta.language}</Chip>
      </div>

      <div className="divide-y divide-gray-800">
        <Row icon={<FileCode2 />} label="Files">
          <Chip>{meta.sourceFileCount} source</Chip>
          <Chip>{meta.testFileCount} test</Chip>
          <Chip>{meta.fileCount} total</Chip>
        </Row>

        <Row icon={<FlaskConical />} label="Test frameworks">
          {meta.testFrameworks.length > 0
            ? meta.testFrameworks.map((f) => <Chip key={f}>{f}</Chip>)
            : <span className="text-xs text-gray-600">None detected</span>
          }
        </Row>

        <Row icon={<Package />} label="Dependencies">
          <Chip>{meta.packageManager}</Chip>
          <Chip>{depCount} prod</Chip>
          <Chip>{devDepCount} dev</Chip>
        </Row>

        {meta.framework && (
          <Row icon={<Globe />} label="Framework">
            <Chip>{meta.framework}</Chip>
          </Row>
        )}

        {meta.nodeVersion && (
          <Row icon={<Terminal />} label="Node">
            <Chip>{meta.nodeVersion}</Chip>
          </Row>
        )}

        {meta.gitRemote && (
          <Row icon={<GitBranch />} label="Remote">
            <span className="text-xs text-gray-400 font-mono truncate">{meta.gitRemote}</span>
          </Row>
        )}
      </div>
    </div>
  );
}

import { severityBadgeClass, severityBorderClass, GAP_CATEGORY_LABELS, shortPath } from '../lib/utils';
import { FileCode2, ChevronDown, ChevronRight } from 'lucide-react';
import { useState } from 'react';
import type { TestGap } from '../types';

interface Props {
  gap: TestGap;
}

export default function TestGapCard({ gap }: Props) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div
      className={`border border-gray-800 border-l-4 ${severityBorderClass(gap.severity)} rounded-lg bg-gray-900 overflow-hidden`}
    >
      {/* Header */}
      <button
        className="w-full flex items-start gap-3 p-4 text-left hover:bg-gray-800/40 transition-colors"
        onClick={() => setExpanded((v) => !v)}
      >
        <div className="mt-0.5">
          {expanded
            ? <ChevronDown className="w-4 h-4 text-gray-500" />
            : <ChevronRight className="w-4 h-4 text-gray-500" />
          }
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex flex-wrap items-center gap-2 mb-1">
            <span className={severityBadgeClass(gap.severity)}>
              {gap.severity.toUpperCase()}
            </span>
            <span className="text-xs bg-gray-800 text-gray-400 border border-gray-700 px-2 py-0.5 rounded">
              {GAP_CATEGORY_LABELS[gap.category] ?? gap.category}
            </span>
          </div>
          <p className="text-sm font-medium text-gray-200">{gap.title}</p>
          <div className="flex items-center gap-1.5 mt-1">
            <FileCode2 className="w-3 h-3 text-gray-600" />
            <span className="text-xs text-gray-500 font-mono">
              {shortPath(gap.filePath)}
              {gap.lineStart && `:${gap.lineStart}`}
            </span>
          </div>
        </div>
      </button>

      {/* Expanded detail */}
      {expanded && (
        <div className="px-4 pb-4 pt-0 border-t border-gray-800/60 space-y-3">
          <p className="text-sm text-gray-300 leading-relaxed">{gap.description}</p>

          <div className="bg-gray-950 rounded-lg p-3 border border-gray-800">
            <p className="text-xs text-gray-500 uppercase tracking-wide mb-1.5 font-medium">
              Why this matters
            </p>
            <p className="text-xs text-gray-400 leading-relaxed">{gap.rationale}</p>
          </div>

          {gap.suggestedTestTitle && (
            <div>
              <p className="text-xs text-gray-500 uppercase tracking-wide mb-1.5 font-medium">
                Suggested test
              </p>
              <code className="block text-xs text-green-400 font-mono bg-gray-950 border border-gray-800 rounded px-3 py-2">
                it('{gap.suggestedTestTitle}', ...)
              </code>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { severityBadgeClass, severityBorderClass, ISSUE_CATEGORY_LABELS, shortPath } from '../lib/utils';
import { FileCode2, ChevronDown, ChevronRight, Wrench } from 'lucide-react';
import { useState } from 'react';
import type { ConfigIssue } from '../types';

interface Props {
  issue: ConfigIssue;
}

export default function ConfigIssueCard({ issue }: Props) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div
      className={`border border-gray-800 border-l-4 ${severityBorderClass(issue.severity)} rounded-lg bg-gray-900 overflow-hidden`}
    >
      <button
        className="w-full flex items-start gap-3 p-4 text-left hover:bg-gray-800/40 transition-colors"
        onClick={() => setExpanded((v) => !v)}
      >
        <div className="mt-0.5">
          {expanded
            ? <ChevronDown className="w-4 h-4 text-gray-500" />
            : <ChevronRight className="w-4 h-4 text-gray-500" />
          }
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex flex-wrap items-center gap-2 mb-1">
            <span className={severityBadgeClass(issue.severity)}>
              {issue.severity.toUpperCase()}
            </span>
            <span className="text-xs bg-gray-800 text-gray-400 border border-gray-700 px-2 py-0.5 rounded">
              {ISSUE_CATEGORY_LABELS[issue.category] ?? issue.category}
            </span>
          </div>
          <p className="text-sm font-medium text-gray-200">{issue.title}</p>
          {issue.filePath && (
            <div className="flex items-center gap-1.5 mt-1">
              <FileCode2 className="w-3 h-3 text-gray-600" />
              <span className="text-xs text-gray-500 font-mono">
                {shortPath(issue.filePath)}
                {issue.line && `:${issue.line}`}
              </span>
            </div>
          )}
        </div>
      </button>

      {expanded && (
        <div className="px-4 pb-4 pt-0 border-t border-gray-800/60 space-y-3">
          <p className="text-sm text-gray-300 leading-relaxed">{issue.description}</p>

          <div className="bg-gray-950 rounded-lg p-3 border border-gray-800">
            <div className="flex items-center gap-1.5 mb-1.5">
              <Wrench className="w-3.5 h-3.5 text-blue-400" />
              <p className="text-xs text-gray-500 uppercase tracking-wide font-medium">
                Recommendation
              </p>
            </div>
            <p className="text-xs text-gray-300 leading-relaxed">{issue.recommendation}</p>
          </div>

          {issue.affectedFiles && issue.affectedFiles.length > 0 && (
            <div>
              <p className="text-xs text-gray-500 uppercase tracking-wide mb-1.5 font-medium">
                Affected files
              </p>
              <div className="flex flex-wrap gap-1.5">
                {issue.affectedFiles.map((f) => (
                  <span key={f} className="text-xs font-mono text-gray-400 bg-gray-800 border border-gray-700 px-2 py-0.5 rounded">
                    {shortPath(f)}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

