import HealthScoreCard from '../components/HealthScoreCard';
import RepoOverviewCard from '../components/RepoOverviewCard';
import type { AnalysisResult } from '../types';
import { AlertTriangle, ShieldCheck, FlaskConical, Settings2, Clock } from 'lucide-react';

interface Props {
  result: AnalysisResult;
  onTabChange: (tab: 'testing' | 'configuration') => void;
}

interface StatCardProps {
  label: string;
  value: string | number;
  sub?: string;
  color?: string;
  onClick?: () => void;
}

function StatCard({ label, value, sub, color = 'text-white', onClick }: StatCardProps) {
  return (
    <button
      onClick={onClick}
      disabled={!onClick}
      className={[
        'card text-left w-full transition-colors',
        onClick ? 'hover:border-gray-700 cursor-pointer' : 'cursor-default',
      ].join(' ')}
    >
      <p className="text-xs text-gray-500 mb-1.5 uppercase tracking-wide font-medium">{label}</p>
      <p className={`text-3xl font-bold tabular-nums ${color}`}>{value}</p>
      {sub && <p className="text-xs text-gray-500 mt-1">{sub}</p>}
    </button>
  );
}

export default function OverviewPage({ result, onTabChange }: Props) {
  const { repoMetadata: meta, testAnalysis, configAnalysis, healthScore } = result;

  const criticalGaps = testAnalysis.gaps.filter((g) => g.severity === 'critical').length;
  const criticalIssues = configAnalysis.issues.filter((i) => i.severity === 'critical').length;

  return (
    <div className="space-y-5">
      {/* Top row: health + repo */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <HealthScoreCard score={healthScore} />
        <div className="lg:col-span-2">
          <RepoOverviewCard meta={meta} />
        </div>
      </div>

      {/* Stat row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard
          label="Testing gaps"
          value={testAnalysis.gaps.length}
          sub={criticalGaps > 0 ? `${criticalGaps} critical` : 'None critical'}
          color={criticalGaps > 0 ? 'text-red-400' : 'text-white'}
          onClick={() => onTabChange('testing')}
        />
        <StatCard
          label="Config issues"
          value={configAnalysis.issues.length}
          sub={criticalIssues > 0 ? `${criticalIssues} critical` : 'None critical'}
          color={criticalIssues > 0 ? 'text-red-400' : 'text-white'}
          onClick={() => onTabChange('configuration')}
        />
        <StatCard
          label="Est. coverage"
          value={`${testAnalysis.estimatedCoveragePercent}%`}
          sub={`${testAnalysis.totalTestFiles} test files`}
          color={
            testAnalysis.estimatedCoveragePercent >= 70 ? 'text-green-400' :
            testAnalysis.estimatedCoveragePercent >= 40 ? 'text-yellow-400' :
            'text-red-400'
          }
        />
        <StatCard
          label="Untested routes"
          value={testAnalysis.untestedApiRoutes.length}
          sub={`of ${testAnalysis.apiRoutes.length} total routes`}
          color={testAnalysis.untestedApiRoutes.length > 0 ? 'text-orange-400' : 'text-green-400'}
        />
      </div>

      {/* Summary strip */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="card space-y-2">
          <div className="flex items-center gap-2 mb-3">
            <FlaskConical className="w-4 h-4 text-purple-400" />
            <span className="text-sm font-semibold text-gray-200">Test Health Summary</span>
          </div>
          <p className="text-sm text-gray-400 leading-relaxed">{testAnalysis.summary}</p>
        </div>
        <div className="card space-y-2">
          <div className="flex items-center gap-2 mb-3">
            <Settings2 className="w-4 h-4 text-cyan-400" />
            <span className="text-sm font-semibold text-gray-200">Configuration Summary</span>
          </div>
          <p className="text-sm text-gray-400 leading-relaxed">{configAnalysis.summary}</p>
        </div>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-end gap-2 text-xs text-gray-600">
        <Clock className="w-3.5 h-3.5" />
        <span>Analyzed {new Date(result.completedAt).toLocaleString()}</span>
      </div>
    </div>
  );
}

