import type { AnalysisResult } from '../types';
import { CheckCircle2, XCircle, Clock, Terminal, FileCode2 } from 'lucide-react';
import { formatDuration, shortPath } from '../lib/utils';

interface Props {
  result: AnalysisResult;
}

export default function ValidationPage({ result }: Props) {
  const run = result.testRunResult;
  const generated = result.generatedTests ?? [];

  return (
    <div className="space-y-5">
      {/* Test run result */}
      <div className="card">
        <div className="flex items-center gap-2 mb-4">
          <Terminal className="w-4 h-4 text-green-400" />
          <span className="text-sm font-semibold text-gray-200">Test Execution</span>
        </div>

        {!run ? (
          <div className="text-center py-8">
            <Terminal className="w-8 h-8 text-gray-700 mx-auto mb-3" />
            <p className="text-sm text-gray-500">Tests were not run during this analysis.</p>
            <p className="text-xs text-gray-600 mt-1">
              Enable "Run existing tests" and re-analyze to see results here.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {/* Stats */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              <div className="card text-center py-3">
                <p className={`text-2xl font-bold tabular-nums ${run.status === 'passed' ? 'text-green-400' : 'text-red-400'}`}>
                  {run.status === 'passed' ? '✓' : '✗'}
                </p>
                <p className="text-xs text-gray-500 mt-1">{run.status}</p>
              </div>
              <div className="card text-center py-3">
                <p className="text-2xl font-bold text-green-400 tabular-nums">{run.passed}</p>
                <p className="text-xs text-gray-500 mt-1">passed</p>
              </div>
              <div className="card text-center py-3">
                <p className={`text-2xl font-bold tabular-nums ${run.failed > 0 ? 'text-red-400' : 'text-white'}`}>
                  {run.failed}
                </p>
                <p className="text-xs text-gray-500 mt-1">failed</p>
              </div>
              <div className="card text-center py-3">
                <div className="flex items-center justify-center gap-1 text-gray-400 mb-1">
                  <Clock className="w-4 h-4" />
                </div>
                <p className="text-sm font-mono text-gray-300 tabular-nums">
                  {run.duration ? formatDuration(run.duration) : '—'}
                </p>
                <p className="text-xs text-gray-500">duration</p>
              </div>
            </div>

            {/* Failed tests */}
            {run.failedTests.length > 0 && (
              <div>
                <h4 className="text-xs text-gray-500 uppercase tracking-wide mb-2 font-medium flex items-center gap-1.5">
                  <XCircle className="w-3.5 h-3.5 text-red-400" />
                  Failed Tests ({run.failedTests.length})
                </h4>
                <div className="space-y-2">
                  {run.failedTests.map((t, i) => (
                    <div key={i} className="border border-red-900 bg-red-950/30 rounded-lg p-3">
                      <p className="text-sm font-medium text-red-300 mb-1">{t.name}</p>
                      <pre className="text-xs text-red-400/80 font-mono whitespace-pre-wrap overflow-x-auto">{t.error}</pre>
                      {t.file && (
                        <p className="text-xs text-gray-600 font-mono mt-2">{shortPath(t.file)}</p>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Terminal output */}
            {run.output && (
              <div>
                <h4 className="text-xs text-gray-500 uppercase tracking-wide mb-2 font-medium">
                  Terminal Output
                </h4>
                <pre className="text-xs font-mono text-gray-400 bg-gray-950 border border-gray-800 rounded-lg p-4 overflow-x-auto max-h-80 whitespace-pre-wrap">
                  {run.output}
                </pre>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Generated tests */}
      <div className="card">
        <div className="flex items-center gap-2 mb-4">
          <FileCode2 className="w-4 h-4 text-purple-400" />
          <span className="text-sm font-semibold text-gray-200">Generated Tests</span>
          <span className="ml-auto text-xs text-gray-600">{generated.length} file(s)</span>
        </div>

        {generated.length === 0 ? (
          <div className="text-center py-8">
            <FileCode2 className="w-8 h-8 text-gray-700 mx-auto mb-3" />
            <p className="text-sm text-gray-500">No tests were generated.</p>
            <p className="text-xs text-gray-600 mt-1">
              Enable "Generate test suggestions" and re-analyze to see generated tests here.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {generated.map((t) => (
              <div key={t.filePath} className="border border-gray-800 rounded-lg overflow-hidden">
                <div className="flex items-center justify-between px-4 py-2.5 bg-gray-800/50 border-b border-gray-800">
                  <div className="flex items-center gap-2">
                    <FileCode2 className="w-3.5 h-3.5 text-gray-500" />
                    <span className="text-xs font-mono text-gray-300">{t.filePath}</span>
                  </div>
                  <span className="text-xs text-gray-600">{t.framework}</span>
                </div>
                <pre className="text-xs font-mono text-gray-300 bg-gray-950 p-4 overflow-x-auto max-h-64 whitespace-pre">
                  {t.content}
                </pre>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import type { AnalysisResult } from '../types';
import { gradeColor, severityBadgeClass } from '../lib/utils';
import { Shield, Download, Clock } from 'lucide-react';
import HealthScoreCard from '../components/HealthScoreCard';

interface Props {
  result: AnalysisResult;
}

export default function ReportPage({ result }: Props) {
  const { repoMetadata: meta, testAnalysis, configAnalysis, risks, healthScore } = result;

  const topRisks = [...risks].sort((a, b) => {
    const order = { critical: 0, high: 1, medium: 2, low: 3 };
    return order[a.level] - order[b.level];
  });

  function downloadReport() {
    const blob = new Blob([JSON.stringify(result, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `devguard-report-${meta.name}-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }

  return (
    <div className="space-y-5">
      {/* Report header */}
      <div className="card">
        <div className="flex items-start justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-600/20 border border-blue-500/30 flex items-center justify-center">
              <Shield className="w-5 h-5 text-blue-400" />
            </div>
            <div>
              <h2 className="text-base font-semibold text-white">DevGuard Health Report</h2>
              <p className="text-xs text-gray-400 font-mono">{meta.name}</p>
            </div>
          </div>
          <button onClick={downloadReport} className="btn-secondary text-xs">
            <Download className="w-3.5 h-3.5" />
            Download JSON
          </button>
        </div>

        <div className="mt-4 flex items-center gap-2 text-xs text-gray-600">
          <Clock className="w-3.5 h-3.5" />
          <span>Generated {new Date(result.completedAt).toLocaleString()}</span>
          <span className="mx-2 text-gray-800">·</span>
          <span>Session {result.sessionId.slice(0, 8)}</span>
        </div>
      </div>

      {/* Health summary */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <HealthScoreCard score={healthScore} />
        <div className="lg:col-span-2 card">
          <h3 className="text-xs text-gray-500 uppercase tracking-wide font-medium mb-4">
            Findings Summary
          </h3>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
            {[
              { label: 'Testing gaps', value: testAnalysis.gaps.length },
              { label: 'Config issues', value: configAnalysis.issues.length },
              { label: 'Untested routes', value: testAnalysis.untestedApiRoutes.length },
              { label: 'Missing env vars', value: configAnalysis.envVars.filter(v => v.usedIn.length > 0 && v.definedIn.length === 0).length },
              { label: 'Critical risks', value: risks.filter(r => r.level === 'critical').length },
              { label: 'Est. coverage', value: `${testAnalysis.estimatedCoveragePercent}%` },
            ].map(({ label, value }) => (
              <div key={label}>
                <p className="text-xs text-gray-500 mb-0.5">{label}</p>
                <p className="text-xl font-bold tabular-nums text-white">{value}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Top risks */}
      {topRisks.length > 0 && (
        <div>
          <h3 className="text-xs text-gray-500 uppercase tracking-wide font-medium mb-3">
            Prioritized Risks ({topRisks.length})
          </h3>
          <div className="space-y-2">
            {topRisks.map((risk) => (
              <div
                key={risk.id}
                className="card flex items-start gap-4"
              >
                <div className="mt-0.5">
                  <span className={severityBadgeClass(risk.level)}>
                    {risk.level.toUpperCase()}
                  </span>
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-200 mb-1">{risk.title}</p>
                  <p className="text-xs text-gray-400 leading-relaxed mb-2">{risk.description}</p>
                  <div className="bg-gray-800/50 rounded p-2.5 border border-gray-700/50">
                    <p className="text-xs text-gray-500 font-medium mb-1">Recommendation</p>
                    <p className="text-xs text-gray-300 leading-relaxed">{risk.recommendation}</p>
                  </div>
                  <p className="text-xs text-gray-600 mt-2">Impact: {risk.estimatedImpact}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Grade */}
      <div className="card text-center py-8">
        <p className="text-xs text-gray-500 uppercase tracking-wide mb-2 font-medium">
          Final Grade
        </p>
        <p className={`text-8xl font-bold tabular-nums ${gradeColor(healthScore.grade)}`}>
          {healthScore.grade}
        </p>
        <p className="text-sm text-gray-500 mt-2">
          Overall score: {healthScore.overall}/100
        </p>
      </div>
    </div>
  );
}

