import { useState, useCallback, useRef, useEffect } from 'react';
import Header from './components/Header';
import RepoSelector from './components/RepoSelector';
import AnalysisProgress from './components/AnalysisProgress';
import EmptyDashboard from './pages/EmptyDashboard';
import OverviewPage from './pages/OverviewPage';
import TestingPage from './pages/TestingPage';
import ConfigurationPage from './pages/ConfigurationPage';
import ValidationPage from './pages/ValidationPage';
import ReportPage from './pages/ReportPage';
import { api } from './api/client';
import type { ActiveTab, SessionStatus, Progress, AnalysisResult } from './types';

// Absolute path to the demo repository (relative to devguard project root)
const DEMO_REPO_PATH = `${window.location.protocol}//${window.location.hostname}` === 'http://localhost'
  ? `${import.meta.env.VITE_DEMO_REPO_PATH ?? './demo-repository'}`
  : './demo-repository';

export default function App() {
  const [activeTab, setActiveTab] = useState<ActiveTab>('overview');
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [sessionStatus, setSessionStatus] = useState<SessionStatus>('idle');
  const [progress, setProgress] = useState<Progress | null>(null);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const stopPolling = useCallback(() => {
    if (pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
  }, []);

  // Poll the session status until done or errored
  const startPolling = useCallback((id: string) => {
    stopPolling();
    pollRef.current = setInterval(async () => {
      try {
        const status = await api.getStatus(id);
        setSessionStatus(status.status as SessionStatus);
        if (status.progress) setProgress(status.progress as Progress);
        if (status.error) setError(status.error);

        if (status.status === 'complete') {
          stopPolling();
          const res = await api.getResult(id);
          setResult(res as AnalysisResult);
        } else if (status.status === 'error') {
          stopPolling();
        }
      } catch (err) {
        stopPolling();
        setError(err instanceof Error ? err.message : 'Failed to poll session status');
        setSessionStatus('error');
      }
    }, 1200);
  }, [stopPolling]);

  useEffect(() => () => stopPolling(), [stopPolling]);

  async function handleAnalyze(
    repoPath: string,
    opts: { runTests: boolean; generateTests: boolean }
  ) {
    setError(null);
    setResult(null);
    setProgress(null);
    setActiveTab('overview');

    try {
      const { sessionId: id } = await api.startAnalysis({
        repoPath,
        runTests: opts.runTests,
        generateTests: opts.generateTests,
      });
      setSessionId(id);
      setSessionStatus('ingesting');
      startPolling(id);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to start analysis');
      setSessionStatus('error');
    }
  }

  async function handleDemo() {
    // Use the demo-repository path — resolved relative to where the backend runs
    await handleAnalyze('./demo-repository', { runTests: false, generateTests: true });
  }

  const isLoading = sessionStatus !== 'idle' && sessionStatus !== 'complete' && sessionStatus !== 'error';
  const hasResult = result !== null;

  function renderContent() {
    if (isLoading) {
      return <AnalysisProgress status={sessionStatus} progress={progress} />;
    }

    if (!hasResult) {
      return <EmptyDashboard />;
    }

    switch (activeTab) {
      case 'overview':
        return (
          <OverviewPage
            result={result}
            onTabChange={(tab) => setActiveTab(tab)}
          />
        );
      case 'testing':
        return <TestingPage analysis={result.testAnalysis} />;
      case 'configuration':
        return <ConfigurationPage analysis={result.configAnalysis} />;
      case 'validation':
        return <ValidationPage result={result} />;
      case 'report':
        return <ReportPage result={result} />;
    }
  }

  return (
    <div className="min-h-screen bg-gray-950 flex flex-col">
      <Header
        activeTab={activeTab}
        onTabChange={setActiveTab}
        hasResult={hasResult}
      />

      <main className="flex-1 max-w-screen-xl mx-auto w-full px-6 py-6 space-y-5">
        <RepoSelector
          onAnalyze={handleAnalyze}
          onDemo={handleDemo}
          isLoading={isLoading}
          error={error}
        />

        <div>{renderContent()}</div>
      </main>
    </div>
  );
}

