interface StatCardProps {
  label: string;
  value: string | number;
  sub?: string;
  color?: string;
  onClick?: () => void;
}

function StatCard({ label, value, sub, color = 'text-white', onClick }: StatCardProps) {
  return (
    <button
      onClick={onClick}
      disabled={!onClick}
      className={[
        'card text-left w-full transition-colors',
        onClick ? 'hover:border-gray-700 cursor-pointer' : 'cursor-default',
      ].join(' ')}
    >
      <p className="text-xs text-gray-500 mb-1.5 uppercase tracking-wide font-medium">{label}</p>
      <p className={`text-3xl font-bold tabular-nums ${color}`}>{value}</p>
      {sub && <p className="text-xs text-gray-500 mt-1">{sub}</p>}
    </button>
  );
}

export default function OverviewPage({ result, onTabChange }: Props) {
  const { repoMetadata: meta, testAnalysis, configAnalysis, healthScore } = result;

  const criticalGaps = testAnalysis.gaps.filter((g) => g.severity === 'critical').length;
  const criticalIssues = configAnalysis.issues.filter((i) => i.severity === 'critical').length;

  return (
    <div className="space-y-5">
      {/* Top row: health + repo */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
