        <div className="lg:col-span-2">
          <RepoOverviewCard meta={meta} />
        </div>
      </div>

      {/* Stat row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard
          label="Testing gaps"
          value={testAnalysis.gaps.length}
          sub={criticalGaps > 0 ? `${criticalGaps} critical` : 'None critical'}
          color={criticalGaps > 0 ? 'text-red-400' : 'text-white'}
          onClick={() => onTabChange('testing')}
        />
        <StatCard
          label="Config issues"
          value={configAnalysis.issues.length}
          sub={criticalIssues > 0 ? `${criticalIssues} critical` : 'None critical'}
          color={criticalIssues > 0 ? 'text-red-400' : 'text-white'}
          onClick={() => onTabChange('configuration')}
        />
        <StatCard
          label="Est. coverage"
          value={`${testAnalysis.estimatedCoveragePercent}%`}
          sub={`${testAnalysis.totalTestFiles} test files`}
          color={
            testAnalysis.estimatedCoveragePercent >= 70 ? 'text-green-400' :
            testAnalysis.estimatedCoveragePercent >= 40 ? 'text-yellow-400' :
