          sub={`of ${testAnalysis.apiRoutes.length} total routes`}
          color={testAnalysis.untestedApiRoutes.length > 0 ? 'text-orange-400' : 'text-green-400'}
        />
      </div>

      {/* Summary strip */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="card space-y-2">
          <div className="flex items-center gap-2 mb-3">
            <FlaskConical className="w-4 h-4 text-purple-400" />
            <span className="text-sm font-semibold text-gray-200">Test Health Summary</span>
