// ─── Core domain types for the DevGuard backend ────────────────────────────
// Single source of truth — all analyzers and routes import from here.

// ─── Analysis Session ────────────────────────────────────────────────────────

export type AnalysisStatus =
  | 'pending'
  | 'scanning'
  | 'analyzing'
  | 'complete'
  | 'error';

export interface Analysis {
  id: string;
  status: AnalysisStatus;
  repositoryPath: string;
  createdAt: string;
  completedAt?: string;
  error?: string;
  result?: AnalysisResult;
}

// ─── Repository Profile ───────────────────────────────────────────────────────

export type Language = 'typescript' | 'javascript' | 'mixed' | 'unknown';
export type PackageManager = 'npm' | 'yarn' | 'pnpm' | 'unknown';
export type TestFramework = 'jest' | 'vitest' | 'mocha' | 'jasmine' | 'ava' | 'unknown';

export interface RepositoryProfile {
  name: string;
  description?: string;
  language: Language;
  packageManager: PackageManager;
  framework?: string;
  testFrameworks: TestFramework[];
  nodeVersion?: string;
  isMonorepo: boolean;
  workspaces: string[];
  // dependencies
  dependencies: Record<string, string>;
  devDependencies: Record<string, string>;
  scripts: Record<string, string>;
  // git
  isGitRepo: boolean;
  gitRemote?: string;
  // file counts
  totalFiles: number;
  sourceFiles: string[];
  testFiles: string[];
  configFiles: string[];
  // entry points
  entryPoints: string[];
  hasTypes: boolean;
}

// ─── Code Symbol ─────────────────────────────────────────────────────────────

export type SymbolKind =
  | 'function'
  | 'class'
  | 'method'
  | 'arrow_function'
  | 'export'
  | 'route_handler'
  | 'middleware'
  | 'controller'
  | 'service'
  | 'utility';

export type SymbolImportance = 'critical' | 'high' | 'medium' | 'low';

export interface CodeSymbol {
  name: string;
  kind: SymbolKind;
  filePath: string;
  lineStart: number;
  lineEnd: number;
  isExported: boolean;
  importance: SymbolImportance;
  importanceReasons: string[];
  isAsync: boolean;
  paramCount: number;
}

// ─── Route Info ───────────────────────────────────────────────────────────────

export interface RouteInfo {
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'ALL' | string;
  path: string;
  filePath: string;
  handlerName?: string;
  line: number;
}

// ─── Test Profile ─────────────────────────────────────────────────────────────

export interface TestSuite {
  filePath: string;
  framework: TestFramework;
  testCount: number;
  describeBlocks: string[];
  itBlocks: string[];
  importsUnder: string[]; // files this test imports/covers
}

export interface TestProfile {
  totalTestFiles: number;
  totalTestCount: number;
  suites: TestSuite[];
  coveredFiles: Set<string>;
}

// ─── Config Scan ──────────────────────────────────────────────────────────────

export interface EnvVarInfo {
  name: string;
  /** Where this variable is declared (e.g. .env.example, docker-compose.yml) */
  definedIn: string[];
  /** Source files that reference process.env.NAME */
  usedIn: string[];
  hasDefault: boolean;
  /** True if name matches a secret pattern — value is ALWAYS redacted */
  isSecret: boolean;
}

export interface PortMention {
  port: number;
  filePath: string;
  /** Short surrounding text — no secret values */
  context: string;
  line: number;
}

// ─── Analysis Result ──────────────────────────────────────────────────────────

export interface AnalysisResult {
  analysisId: string;
  repositoryProfile: RepositoryProfile;
  symbols: CodeSymbol[];
  routes: RouteInfo[];
  testProfile: TestProfile;
  envVars: EnvVarInfo[];
  portMentions: PortMention[];
  scannedAt: string;
}

// ─── API shapes ───────────────────────────────────────────────────────────────

export interface AnalyzeRequest {
  repositoryPath: string;
}

export interface ApiError {
  error: string;
  detail?: string;
}

import path from 'path';
import fs from 'fs';

/** Patterns that indicate a secret variable — matched case-insensitively against env var names */
const SECRET_PATTERNS = [
  /secret/i,
  /password/i,
  /passwd/i,
  /api[_-]?key/i,
  /auth[_-]?token/i,
  /access[_-]?token/i,
  /private[_-]?key/i,
  /credential/i,
  /jwt[_-]?secret/i,
  /signing[_-]?key/i,
  /encryption[_-]?key/i,
  /database[_-]?url/i,
  /db[_-]?pass/i,
];

/** Returns true if the variable name looks like it holds a secret value. */
export function isSecretName(name: string): boolean {
  return SECRET_PATTERNS.some((re) => re.test(name));
}

/** Redact a secret value for safe display — never returns the real value. */
export function redactValue(_value: string): string {
  return 'REDACTED';
}

/**
 * Resolve and sanitize a repository path.
 * Throws if the path is unsafe, doesn't exist, or isn't a directory.
 */
export function resolveRepoPath(inputPath: string): string {
  if (!inputPath || typeof inputPath !== 'string') {
    throw new Error('Repository path must be a non-empty string');
  }

  // Resolve to absolute path
  const resolved = path.resolve(inputPath);

  // Reject path traversal attempts
  if (inputPath.includes('..') && !path.isAbsolute(inputPath)) {
    throw new Error('Path traversal is not allowed');
  }

  // Must exist
  if (!fs.existsSync(resolved)) {
    throw new Error(`Repository path does not exist: ${resolved}`);
  }

  // Must be a directory
  const stat = fs.statSync(resolved);
  if (!stat.isDirectory()) {
    throw new Error(`Repository path must be a directory: ${resolved}`);
  }

  return resolved;
}

/** Return the last path segment (directory name) as the project name. */
export function repoName(repoPath: string): string {
  return path.basename(repoPath);
}

/** Read a file safely — returns null instead of throwing. */
export function readFileSafe(filePath: string): string | null {
  try {
    return fs.readFileSync(filePath, 'utf-8');
  } catch {
    return null;
  }
}

/** Parse JSON safely — returns null on failure. */
export function parseJsonSafe<T = unknown>(content: string): T | null {
  try {
    return JSON.parse(content) as T;
  } catch {
    return null;
  }
}

/** Check if a file exists. */
export function fileExists(filePath: string): boolean {
  return fs.existsSync(filePath);
}

/** Normalise a file path to forward slashes for consistent output. */
export function normalizePath(p: string): string {
  return p.replace(/\\/g, '/');
}

/** Return the relative path from repoRoot, with forward slashes. */
export function relativePath(repoRoot: string, absPath: string): string {
  return normalizePath(path.relative(repoRoot, absPath));
}

