// ─── Core domain types for the DevGuard backend ────────────────────────────
// Single source of truth — all analyzers and routes import from here.

// ─── Analysis Session ────────────────────────────────────────────────────────

export type AnalysisStatus =
  | 'pending'
  | 'scanning'
  | 'analyzing'
  | 'complete'
  | 'error';

export interface Analysis {
  id: string;
  status: AnalysisStatus;
  repositoryPath: string;
  createdAt: string;
  completedAt?: string;
  error?: string;
  result?: AnalysisResult;
}

// ─── Repository Profile ───────────────────────────────────────────────────────

export type Language = 'typescript' | 'javascript' | 'mixed' | 'unknown';
export type PackageManager = 'npm' | 'yarn' | 'pnpm' | 'unknown';
export type TestFramework = 'jest' | 'vitest' | 'mocha' | 'jasmine' | 'ava' | 'unknown';

export interface RepositoryProfile {
  name: string;
  description?: string;
  language: Language;
  packageManager: PackageManager;
  framework?: string;
  testFrameworks: TestFramework[];
  nodeVersion?: string;
  isMonorepo: boolean;
  workspaces: string[];
  // dependencies
  dependencies: Record<string, string>;
  devDependencies: Record<string, string>;
  scripts: Record<string, string>;
  // git
  isGitRepo: boolean;
  gitRemote?: string;
  // file counts
  totalFiles: number;
  sourceFiles: string[];
  testFiles: string[];
  configFiles: string[];
  // entry points
  entryPoints: string[];
  hasTypes: boolean;
}

// ─── Code Symbol ─────────────────────────────────────────────────────────────

export type SymbolKind =
  | 'function'
  | 'class'
  | 'method'
  | 'arrow_function'
  | 'export'
  | 'route_handler'
  | 'middleware'
  | 'controller'
  | 'service'
  | 'utility';

export type SymbolImportance = 'critical' | 'high' | 'medium' | 'low';

export interface CodeSymbol {
  name: string;
  kind: SymbolKind;
  filePath: string;
  lineStart: number;
  lineEnd: number;
  isExported: boolean;
  importance: SymbolImportance;
  importanceReasons: string[];
  isAsync: boolean;
  paramCount: number;
}

// ─── Route Info ───────────────────────────────────────────────────────────────

export interface RouteInfo {
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'ALL' | string;
  path: string;
  filePath: string;
  handlerName?: string;
  line: number;
}

// ─── Test Profile ─────────────────────────────────────────────────────────────

export interface TestSuite {
  filePath: string;
  framework: TestFramework;
  testCount: number;
  describeBlocks: string[];
  itBlocks: string[];
  importsUnder: string[]; // files this test imports/covers
}

export interface TestProfile {
  totalTestFiles: number;
  totalTestCount: number;
  suites: TestSuite[];
  coveredFiles: Set<string>;
}

// ─── Config Scan ──────────────────────────────────────────────────────────────

export interface EnvVarInfo {
  name: string;
  /** Where this variable is declared (e.g. .env.example, docker-compose.yml) */
  definedIn: string[];
  /** Source files that reference process.env.NAME */
  usedIn: string[];
  hasDefault: boolean;
  /** True if name matches a secret pattern — value is ALWAYS redacted */
  isSecret: boolean;
}

export interface PortMention {
  port: number;
  filePath: string;
  /** Short surrounding text — no secret values */
  context: string;
  line: number;
}

// ─── Analysis Result ──────────────────────────────────────────────────────────

export interface AnalysisResult {
  analysisId: string;
  repositoryProfile: RepositoryProfile;
  symbols: CodeSymbol[];
  routes: RouteInfo[];
  testProfile: TestProfile;
  envVars: EnvVarInfo[];
  portMentions: PortMention[];
  scannedAt: string;
}

// ─── API shapes ───────────────────────────────────────────────────────────────

export interface AnalyzeRequest {
  repositoryPath: string;
}

export interface ApiError {
  error: string;
  detail?: string;
}

