import path from 'path';
import fs from 'fs';

/** Patterns that indicate a secret variable — matched case-insensitively against env var names */
const SECRET_PATTERNS = [
  /secret/i,
  /password/i,
  /passwd/i,
  /api[_-]?key/i,
  /auth[_-]?token/i,
  /access[_-]?token/i,
  /private[_-]?key/i,
  /credential/i,
  /jwt[_-]?secret/i,
  /signing[_-]?key/i,
  /encryption[_-]?key/i,
  /database[_-]?url/i,
  /db[_-]?pass/i,
];

/** Returns true if the variable name looks like it holds a secret value. */
export function isSecretName(name: string): boolean {
  return SECRET_PATTERNS.some((re) => re.test(name));
}

/** Redact a secret value for safe display — never returns the real value. */
export function redactValue(_value: string): string {
  return 'REDACTED';
}

/**
 * Resolve and sanitize a repository path.
 * Throws if the path is unsafe, doesn't exist, or isn't a directory.
 */
export function resolveRepoPath(inputPath: string): string {
  if (!inputPath || typeof inputPath !== 'string') {
    throw new Error('Repository path must be a non-empty string');
  }

  // Resolve to absolute path
  const resolved = path.resolve(inputPath);

  // Reject path traversal attempts
  if (inputPath.includes('..') && !path.isAbsolute(inputPath)) {
    throw new Error('Path traversal is not allowed');
  }

  // Must exist
  if (!fs.existsSync(resolved)) {
    throw new Error(`Repository path does not exist: ${resolved}`);
  }

  // Must be a directory
  const stat = fs.statSync(resolved);
  if (!stat.isDirectory()) {
    throw new Error(`Repository path must be a directory: ${resolved}`);
  }

  return resolved;
}

/** Return the last path segment (directory name) as the project name. */
export function repoName(repoPath: string): string {
  return path.basename(repoPath);
}

/** Read a file safely — returns null instead of throwing. */
export function readFileSafe(filePath: string): string | null {
  try {
    return fs.readFileSync(filePath, 'utf-8');
  } catch {
    return null;
  }
}

/** Parse JSON safely — returns null on failure. */
export function parseJsonSafe<T = unknown>(content: string): T | null {
  try {
    return JSON.parse(content) as T;
  } catch {
    return null;
  }
}

/** Check if a file exists. */
export function fileExists(filePath: string): boolean {
  return fs.existsSync(filePath);
}

/** Normalise a file path to forward slashes for consistent output. */
export function normalizePath(p: string): string {
  return p.replace(/\\/g, '/');
}

/** Return the relative path from repoRoot, with forward slashes. */
export function relativePath(repoRoot: string, absPath: string): string {
  return normalizePath(path.relative(repoRoot, absPath));
}

