import path from 'path';
import fs from 'fs';
import fg from 'fast-glob';
import { readFileSafe, parseJsonSafe, fileExists, relativePath, repoName } from '../utils/security';
import type {
  RepositoryProfile,
  Language,
  PackageManager,
  TestFramework,
} from '../types';

// ─── Patterns ─────────────────────────────────────────────────────────────────

const SOURCE_EXTENSIONS = ['ts', 'tsx', 'js', 'jsx', 'mjs', 'cjs'];
const TEST_PATTERNS = [
  '**/*.test.ts', '**/*.test.tsx', '**/*.test.js', '**/*.test.jsx',
  '**/*.spec.ts', '**/*.spec.tsx', '**/*.spec.js', '**/*.spec.jsx',
  '**/__tests__/**/*.{ts,tsx,js,jsx}',
  '**/test/**/*.{ts,tsx,js,jsx}',
  '**/tests/**/*.{ts,tsx,js,jsx}',
];

const CONFIG_FILE_NAMES = [
  'package.json', 'tsconfig.json', 'tsconfig.*.json',
  '.env.example', '.env.sample', '.env.template',
  'Dockerfile', 'docker-compose.yml', 'docker-compose.yaml',
  '.github/workflows/*.yml', '.github/workflows/*.yaml',
  '.gitlab-ci.yml', '.circleci/config.yml',
  'jest.config.*', 'vitest.config.*', '.mocharc.*',
  'vite.config.*', 'webpack.config.*', 'rollup.config.*',
  '.eslintrc*', '.prettierrc*', '.babelrc*',
  'README.md', 'README.MD', 'readme.md',
];

const IGNORE_DIRS = [
  '**/node_modules/**',
  '**/.git/**',
  '**/dist/**',
  '**/build/**',
  '**/coverage/**',
  '**/.cache/**',
  '**/.turbo/**',
  '**/out/**',
  '**/.next/**',
  '**/.nuxt/**',
  '**/.svelte-kit/**',
];

/** Detect language from the presence of .ts/.tsx files vs .js only. */
function detectLanguage(sourceFiles: string[]): Language {
  const hasTS = sourceFiles.some((f) => f.endsWith('.ts') || f.endsWith('.tsx'));
  const hasJS = sourceFiles.some((f) => f.endsWith('.js') || f.endsWith('.jsx') || f.endsWith('.mjs'));
  if (hasTS && hasJS) return 'mixed';
  if (hasTS) return 'typescript';
  if (hasJS) return 'javascript';
  return 'unknown';
}

/** Detect package manager from lockfile presence. */
function detectPackageManager(repoPath: string): PackageManager {
  if (fileExists(path.join(repoPath, 'pnpm-lock.yaml'))) return 'pnpm';
  if (fileExists(path.join(repoPath, 'yarn.lock'))) return 'yarn';
  if (fileExists(path.join(repoPath, 'package-lock.json'))) return 'npm';
  return 'unknown';
}

/** Detect test frameworks from devDependencies and config files. */
function detectTestFrameworks(
  devDeps: Record<string, string>,
  configFiles: string[],
): TestFramework[] {
  const found = new Set<TestFramework>();
  const allKeys = Object.keys(devDeps).map((k) => k.toLowerCase());
  const configNames = configFiles.map((f) => path.basename(f).toLowerCase());

  if (allKeys.some((k) => k === 'jest' || k.startsWith('@jest/'))) found.add('jest');
  if (allKeys.some((k) => k === 'vitest')) found.add('vitest');
  if (allKeys.some((k) => k === 'mocha' || k === '@types/mocha')) found.add('mocha');
  if (allKeys.some((k) => k === 'jasmine' || k === 'jasmine-core')) found.add('jasmine');
  if (allKeys.some((k) => k === 'ava')) found.add('ava');

  // Fallback: config file names
  if (found.size === 0) {
    if (configNames.some((n) => n.startsWith('jest.config'))) found.add('jest');
    if (configNames.some((n) => n.startsWith('vitest.config'))) found.add('vitest');
    if (configNames.some((n) => n.startsWith('.mocharc'))) found.add('mocha');
  }

  return Array.from(found);
}

/** Detect the primary framework from dependencies. */
function detectFramework(
  deps: Record<string, string>,
  devDeps: Record<string, string>,
): string | undefined {
  const all = { ...deps, ...devDeps };
  const keys = Object.keys(all).map((k) => k.toLowerCase());

  if (keys.includes('next')) return 'Next.js';
  if (keys.includes('nuxt') || keys.includes('nuxt3')) return 'Nuxt';
  if (keys.includes('remix')) return 'Remix';
  if (keys.includes('@nestjs/core')) return 'NestJS';
  if (keys.includes('express')) return 'Express';
  if (keys.includes('fastify')) return 'Fastify';
  if (keys.includes('koa')) return 'Koa';
  if (keys.includes('hapi') || keys.includes('@hapi/hapi')) return 'Hapi';
  if (keys.includes('react') && keys.includes('vite')) return 'React + Vite';
  if (keys.includes('react')) return 'React';
  if (keys.includes('vue')) return 'Vue';
  if (keys.includes('svelte')) return 'Svelte';
  if (keys.includes('@angular/core')) return 'Angular';
  return undefined;
}

/** Detect git remote from .git/config. */
function detectGitRemote(repoPath: string): string | undefined {
  const gitConfig = readFileSafe(path.join(repoPath, '.git', 'config'));
  if (!gitConfig) return undefined;
  const match = gitConfig.match(/url\s*=\s*(.+)/);
  return match?.[1]?.trim();
}

/** Find likely entry point files. */
function findEntryPoints(
  repoPath: string,
  scripts: Record<string, string>,
  sourceFiles: string[],
): string[] {
  const entries: string[] = [];

  // From package.json "main" or "module"
  const pkgPath = path.join(repoPath, 'package.json');
  const pkg = parseJsonSafe<Record<string, unknown>>(readFileSafe(pkgPath) ?? '');
  if (pkg?.main && typeof pkg.main === 'string') {
    entries.push(relativePath(repoPath, path.resolve(repoPath, pkg.main)));
  }
  if (pkg?.module && typeof pkg.module === 'string') {
    entries.push(relativePath(repoPath, path.resolve(repoPath, pkg.module as string)));
  }

  // Common entry file names
  const commonEntries = ['src/index.ts', 'src/index.js', 'src/server.ts', 'src/server.js',
    'src/app.ts', 'src/app.js', 'index.ts', 'index.js', 'server.ts', 'server.js', 'app.ts', 'app.js'];
  for (const e of commonEntries) {
    if (fileExists(path.join(repoPath, e))) entries.push(e);
  }

  return [...new Set(entries)].slice(0, 5);
}

/**
 * Scan a repository directory and return its profile.
 * Never modifies the repository — read-only.
 */
export async function analyzeRepository(repoPath: string): Promise<RepositoryProfile> {
  // ── 1. Source files ────────────────────────────────────────────────────────
  const sourceGlob = SOURCE_EXTENSIONS.map((ext) => `**/*.${ext}`);
  const allSourceFiles = await fg(sourceGlob, {
    cwd: repoPath,
    ignore: IGNORE_DIRS,
    absolute: false,
    followSymbolicLinks: false,
  });

  // ── 2. Test files (subset of source files matching test patterns) ──────────
  const testFilesSet = await fg(TEST_PATTERNS, {
    cwd: repoPath,
    ignore: IGNORE_DIRS,
    absolute: false,
    followSymbolicLinks: false,
  });
  const testFilesNorm = new Set(testFilesSet.map((f) => f.replace(/\\/g, '/')));

  const pureSourceFiles = allSourceFiles.filter((f) => !testFilesNorm.has(f.replace(/\\/g, '/')));

  // ── 3. Config files ────────────────────────────────────────────────────────
  const configFiles = await fg(CONFIG_FILE_NAMES, {
    cwd: repoPath,
    ignore: IGNORE_DIRS,
    absolute: false,
    followSymbolicLinks: false,
    dot: true,
  });

  // ── 4. package.json ────────────────────────────────────────────────────────
  interface PackageJson {
    name?: string;
    description?: string;
    version?: string;
    main?: string;
    module?: string;
    dependencies?: Record<string, string>;
    devDependencies?: Record<string, string>;
    scripts?: Record<string, string>;
    engines?: { node?: string };
    workspaces?: string[] | { packages?: string[] };
  }

  const pkgContent = readFileSafe(path.join(repoPath, 'package.json'));
  const pkg = pkgContent ? parseJsonSafe<PackageJson>(pkgContent) : null;
  const dependencies: Record<string, string> = pkg?.dependencies ?? {};
  const devDependencies: Record<string, string> = pkg?.devDependencies ?? {};
  const scripts: Record<string, string> = pkg?.scripts ?? {};
  const nodeVersion = pkg?.engines?.node;

  // Workspaces / monorepo
  let workspaces: string[] = [];
  if (Array.isArray(pkg?.workspaces)) {
    workspaces = pkg.workspaces as string[];
  } else if (pkg?.workspaces && typeof pkg.workspaces === 'object') {
    workspaces = (pkg.workspaces as { packages?: string[] }).packages ?? [];
  }
  const isMonorepo = workspaces.length > 0
    || fileExists(path.join(repoPath, 'pnpm-workspace.yaml'))
    || fileExists(path.join(repoPath, 'lerna.json'));

  // ── 5. Derived attributes ──────────────────────────────────────────────────
  const language = detectLanguage(pureSourceFiles);
  const packageManager = detectPackageManager(repoPath);
  const testFrameworks = detectTestFrameworks(devDependencies, configFiles);
  const framework = detectFramework(dependencies, devDependencies);
  const isGitRepo = fileExists(path.join(repoPath, '.git'));
  const gitRemote = isGitRepo ? detectGitRemote(repoPath) : undefined;
  const hasTypes = fileExists(path.join(repoPath, 'tsconfig.json'))
    || Object.keys(devDependencies).some((d) => d === 'typescript');
  const entryPoints = findEntryPoints(repoPath, scripts, pureSourceFiles);

  // ── 6. Total file count (everything, for context) ─────────────────────────
  const allFiles = await fg('**', {
    cwd: repoPath,
    ignore: IGNORE_DIRS,
    absolute: false,
    followSymbolicLinks: false,
    dot: true,
  });

  return {
    name: pkg?.name ?? repoName(repoPath),
    description: pkg?.description,
    language,
    packageManager,
    framework,
    testFrameworks,
    nodeVersion,
    isMonorepo,
    workspaces,
    dependencies,
    devDependencies,
    scripts,
    isGitRepo,
    gitRemote,
    totalFiles: allFiles.length,
    sourceFiles: pureSourceFiles,
    testFiles: Array.from(testFilesNorm),
    configFiles,
    entryPoints,
    hasTypes,
  };
}

import path from 'path';
import { Project, SourceFile, SyntaxKind, FunctionDeclaration, ArrowFunction, MethodDeclaration, ClassDeclaration } from 'ts-morph';
import { readFileSafe, relativePath } from '../utils/security';
import type { CodeSymbol, RouteInfo, SymbolKind, SymbolImportance } from '../types';

// ─── Importance signals ───────────────────────────────────────────────────────

const AUTH_PATTERNS = /\b(auth|login|logout|register|signup|password|jwt|token|session|permission|role|acl|guard|middleware)\b/i;
const DB_PATTERNS = /\b(db|database|query|model|repository|schema|migration|prisma|mongoose|sequelize|knex|sql|insert|update|delete|find|save)\b/i;
const PAYMENT_PATTERNS = /\b(payment|stripe|paypal|checkout|charge|invoice|billing|subscription|plan|price)\b/i;
const ROUTE_PATTERNS = /\b(router|app|route)\.(get|post|put|patch|delete|use|all)\b/i;
const CRITICAL_NAMES = /^(main|bootstrap|init|start|setup|configure|createApp|createServer)\b/i;

function scoreSymbol(
  name: string,
  filePath: string,
  bodyText: string,
  isExported: boolean,
  paramCount: number,
): { importance: SymbolImportance; reasons: string[] } {
  const reasons: string[] = [];
  let score = 0;

  const combined = `${name} ${filePath} ${bodyText}`;

  if (AUTH_PATTERNS.test(combined)) { reasons.push('authentication/authorization logic'); score += 3; }
  if (DB_PATTERNS.test(combined)) { reasons.push('database operation'); score += 2; }
  if (PAYMENT_PATTERNS.test(combined)) { reasons.push('payment logic'); score += 3; }
  if (ROUTE_PATTERNS.test(bodyText)) { reasons.push('route handler'); score += 2; }
  if (CRITICAL_NAMES.test(name)) { reasons.push('application lifecycle'); score += 2; }
  if (isExported) { reasons.push('exported — part of public API'); score += 1; }
  if (paramCount > 3) { reasons.push('complex signature'); score += 1; }

  // File path signals
  if (/\/(controllers?|handlers?|routes?)\//i.test(filePath)) { reasons.push('controller/route file'); score += 2; }
  if (/\/(services?|usecases?|domain)\//i.test(filePath)) { reasons.push('service layer'); score += 1; }
  if (/\/(middleware|guards?)\//i.test(filePath)) { reasons.push('middleware'); score += 1; }

  const importance: SymbolImportance =
    score >= 5 ? 'critical' :
    score >= 3 ? 'high' :
    score >= 1 ? 'medium' :
    'low';

  return { importance, reasons: reasons.slice(0, 4) };
}

function kindFromNode(node: FunctionDeclaration | ArrowFunction | MethodDeclaration | ClassDeclaration, filePath: string): SymbolKind {
  if (node.getKind() === SyntaxKind.ClassDeclaration) return 'class';
  if (node.getKind() === SyntaxKind.MethodDeclaration) return 'method';
  if (node.getKind() === SyntaxKind.ArrowFunction) return 'arrow_function';
  if (/\/(controllers?|handlers?)\//i.test(filePath)) return 'controller';
  if (/\/(services?)\//i.test(filePath)) return 'service';
  if (/\/(utils?|helpers?|lib)\//i.test(filePath)) return 'utility';
  return 'function';
}

/** Extract route registrations like `router.get('/path', handler)` */
function extractRoutes(sourceFile: SourceFile, repoRoot: string): RouteInfo[] {
  const routes: RouteInfo[] = [];
  const filePath = relativePath(repoRoot, sourceFile.getFilePath());

  sourceFile.forEachDescendant((node) => {
    if (node.getKind() !== SyntaxKind.CallExpression) return;
    const call = node.asKind(SyntaxKind.CallExpression);
    if (!call) return;

    const expr = call.getExpression();
    const exprText = expr.getText();

    // Match: router.get / app.post / this.router.delete etc.
    const match = exprText.match(/(?:^|\.)(get|post|put|patch|delete|all|use)$/i);
    if (!match) return;

    const args = call.getArguments();
    if (args.length === 0) return;

    const firstArg = args[0];
    const routePath = firstArg.getKind() === SyntaxKind.StringLiteral
      ? firstArg.asKind(SyntaxKind.StringLiteral)?.getLiteralValue() ?? firstArg.getText()
      : firstArg.getText();

    // Skip non-path strings (middleware-only registrations)
    if (!routePath.startsWith('/') && !routePath.startsWith("'") && !routePath.startsWith('"')) return;

    const method = match[1].toUpperCase() as RouteInfo['method'];
    const line = node.getStartLineNumber();

    // Try to get handler name
    let handlerName: string | undefined;
    if (args.length >= 2) {
      const lastArg = args[args.length - 1];
      if (lastArg.getKind() === SyntaxKind.Identifier) {
        handlerName = lastArg.getText();
      }
    }

    routes.push({ method, path: routePath, filePath, handlerName, line });
  });

  return routes;
}

/**
 * Analyse JavaScript/TypeScript source files in a repository using AST.
 * Returns CodeSymbols and RouteInfo arrays.
 */
export function analyzeCode(
  repoPath: string,
  sourceFiles: string[],
): { symbols: CodeSymbol[]; routes: RouteInfo[] } {
  const symbols: CodeSymbol[] = [];
  const routes: RouteInfo[] = [];

  if (sourceFiles.length === 0) return { symbols, routes };

  // ts-morph project — we add files manually, no tsconfig needed
  const project = new Project({
    useInMemoryFileSystem: false,
    skipAddingFilesFromTsConfig: true,
    compilerOptions: { allowJs: true },
  });

  // Only analyse up to 150 source files to keep performance reasonable
  const filesToAnalyze = sourceFiles.slice(0, 150);

  for (const rel of filesToAnalyze) {
    const abs = path.join(repoPath, rel);
    try {
      project.addSourceFileAtPath(abs);
    } catch {
      // Skip files that fail to parse (binary, unreadable, etc.)
    }
  }

  for (const sourceFile of project.getSourceFiles()) {
    const filePath = relativePath(repoPath, sourceFile.getFilePath());

    // ── Routes ────────────────────────────────────────────────────────────────
    routes.push(...extractRoutes(sourceFile, repoPath));

    // ── Functions ─────────────────────────────────────────────────────────────
    sourceFile.getFunctions().forEach((fn) => {
      const name = fn.getName();
      if (!name) return; // anonymous

      const body = fn.getBodyText() ?? '';
      const isExported = fn.isExported() || fn.isDefaultExport();
      const params = fn.getParameters().length;
      const { importance, reasons } = scoreSymbol(name, filePath, body, isExported, params);
      const start = fn.getStartLineNumber();
      const end = fn.getEndLineNumber();

      symbols.push({
        name,
        kind: kindFromNode(fn, filePath),
        filePath,
        lineStart: start,
        lineEnd: end,
        isExported,
        importance,
        importanceReasons: reasons,
        isAsync: fn.isAsync(),
        paramCount: params,
      });
    });

    // ── Classes ───────────────────────────────────────────────────────────────
    sourceFile.getClasses().forEach((cls) => {
      const name = cls.getName();
      if (!name) return;

      const isExported = cls.isExported() || cls.isDefaultExport();
      const { importance, reasons } = scoreSymbol(name, filePath, cls.getBodyText() ?? '', isExported, 0);

      symbols.push({
        name,
        kind: 'class',
        filePath,
        lineStart: cls.getStartLineNumber(),
        lineEnd: cls.getEndLineNumber(),
        isExported,
        importance,
        importanceReasons: reasons,
        isAsync: false,
        paramCount: 0,
      });

      // ── Methods ───────────────────────────────────────────────────────────
      cls.getMethods().forEach((method) => {
        const mName = method.getName();
        const mBody = method.getBodyText() ?? '';
        const mExported = isExported; // methods inherit class export
        const mParams = method.getParameters().length;
        const { importance: mImp, reasons: mReasons } = scoreSymbol(
          `${name}.${mName}`, filePath, mBody, mExported, mParams
        );

        symbols.push({
          name: `${name}.${mName}`,
          kind: 'method',
          filePath,
          lineStart: method.getStartLineNumber(),
          lineEnd: method.getEndLineNumber(),
          isExported: mExported,
          importance: mImp,
          importanceReasons: mReasons,
          isAsync: method.isAsync(),
          paramCount: mParams,
        });
      });
    });

    // ── Arrow functions assigned to exported consts ───────────────────────────
    sourceFile.getVariableDeclarations().forEach((decl) => {
      const init = decl.getInitializer();
      if (!init) return;
      if (
        init.getKind() !== SyntaxKind.ArrowFunction &&
        init.getKind() !== SyntaxKind.FunctionExpression
      ) return;

      const name = decl.getName();
      const varStmt = decl.getVariableStatement();
      const isExported = varStmt ? (varStmt.isExported() || varStmt.isDefaultExport()) : false;
      const body = init.getText();
      const params =
        init.getKind() === SyntaxKind.ArrowFunction
          ? (init.asKind(SyntaxKind.ArrowFunction)?.getParameters().length ?? 0)
          : (init.asKind(SyntaxKind.FunctionExpression)?.getParameters().length ?? 0);
      const { importance, reasons } = scoreSymbol(name, filePath, body, isExported, params);

      symbols.push({
        name,
        kind: 'arrow_function',
        filePath,
        lineStart: decl.getStartLineNumber(),
        lineEnd: decl.getEndLineNumber(),
        isExported,
        importance,
        importanceReasons: reasons,
        isAsync: init.getKind() === SyntaxKind.ArrowFunction
          ? (init.asKind(SyntaxKind.ArrowFunction)?.isAsync() ?? false)
          : false,
        paramCount: params,
      });
    });
  }

  return { symbols, routes };
}

import path from 'path';
import fs from 'fs';
import { Project, SyntaxKind } from 'ts-morph';
import fg from 'fast-glob';
import { readFileSafe, relativePath, isSecretName } from '../utils/security';
import type { TestProfile, TestSuite, TestFramework, EnvVarInfo, PortMention } from '../types';

// ─── Test file analysis ───────────────────────────────────────────────────────

const TEST_FRAMEWORK_IMPORTS: Record<string, TestFramework> = {
  'vitest': 'vitest',
  '@jest/globals': 'jest',
  'jest': 'jest',
  'mocha': 'mocha',
  '@types/mocha': 'mocha',
  'jasmine': 'jasmine',
  'ava': 'ava',
};

function detectFrameworkFromImports(sourceFile: ReturnType<InstanceType<typeof Project>['getSourceFiles']>[0]): TestFramework {
  for (const imp of sourceFile.getImportDeclarations()) {
    const mod = imp.getModuleSpecifierValue();
    if (TEST_FRAMEWORK_IMPORTS[mod]) return TEST_FRAMEWORK_IMPORTS[mod];
  }
  // Fallback: check for global describe/it/test usage without imports (jest/mocha globals)
  const text = sourceFile.getFullText();
  if (/\bvitest\b/.test(text)) return 'vitest';
  if (/\bdescribe\b.*\btest\b/.test(text) || /\btest\b/.test(text)) return 'jest';
  return 'unknown';
}

function countTestsInText(text: string): number {
  // Count `it(`, `test(`, `it.each(`, `test.each(`
  const matches = text.match(/\b(?:it|test)\s*[\.(]/g);
  return matches ? matches.length : 0;
}

function extractDescribeBlocks(text: string): string[] {
  const results: string[] = [];
  const re = /describe\s*\(\s*['"`]([^'"`]+)['"`]/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) !== null) results.push(m[1]);
  return results;
}

function extractItBlocks(text: string): string[] {
  const results: string[] = [];
  const re = /(?:it|test)\s*\(\s*['"`]([^'"`]+)['"`]/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) !== null) results.push(m[1]);
  return results.slice(0, 20); // cap for performance
}

function extractTestImports(sourceFile: ReturnType<InstanceType<typeof Project>['getSourceFiles']>[0], repoRoot: string, testFilePath: string): string[] {
  const covered: string[] = [];
  const testDir = path.dirname(path.join(repoRoot, testFilePath));

  for (const imp of sourceFile.getImportDeclarations()) {
    const spec = imp.getModuleSpecifierValue();
    if (!spec.startsWith('.')) continue; // skip node_modules
    // Resolve relative to test file
    const resolved = path.resolve(testDir, spec);
    // Try with and without extension
    const candidates = [resolved, `${resolved}.ts`, `${resolved}.js`, `${resolved}/index.ts`, `${resolved}/index.js`];
    for (const c of candidates) {
      if (fs.existsSync(c)) {
        covered.push(relativePath(repoRoot, c));
        break;
      }
    }
  }
  return covered;
}

/**
 * Analyse test files and build a TestProfile.
 */
export function analyzeTests(repoPath: string, testFiles: string[]): TestProfile {
  const suites: TestSuite[] = [];
  const coveredFiles = new Set<string>();

  if (testFiles.length === 0) {
    return { totalTestFiles: 0, totalTestCount: 0, suites, coveredFiles };
  }

  const project = new Project({
    useInMemoryFileSystem: false,
    skipAddingFilesFromTsConfig: true,
    compilerOptions: { allowJs: true },
  });

  for (const rel of testFiles.slice(0, 100)) {
    try {
      project.addSourceFileAtPath(path.join(repoPath, rel));
    } catch {
      // skip unreadable
    }
  }

  let totalTestCount = 0;

  for (const sourceFile of project.getSourceFiles()) {
    const filePath = relativePath(repoPath, sourceFile.getFilePath());
    const text = sourceFile.getFullText();
    const framework = detectFrameworkFromImports(sourceFile);
    const testCount = countTestsInText(text);
    const describeBlocks = extractDescribeBlocks(text);
    const itBlocks = extractItBlocks(text);
    const importsUnder = extractTestImports(sourceFile, repoPath, filePath);

    totalTestCount += testCount;
    importsUnder.forEach((f) => coveredFiles.add(f));

    suites.push({ filePath, framework, testCount, describeBlocks, itBlocks, importsUnder });
  }

  return { totalTestFiles: testFiles.length, totalTestCount, suites, coveredFiles };
}

// ─── Env var analysis ─────────────────────────────────────────────────────────

const ENV_USAGE_RE = /process\.env\.([A-Z_][A-Z0-9_]*)/g;
const ENV_DEFINE_RE = /^([A-Z_][A-Z0-9_]*)(?:\s*=.*)?$/;

/** Parse a .env-style file and return variable names (values are intentionally ignored). */
function parseEnvFile(content: string): string[] {
  return content
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#'))
    .map((l) => {
      const m = ENV_DEFINE_RE.exec(l);
      return m ? m[1] : null;
    })
    .filter((n): n is string => n !== null);
}

/**
 * Scan all env var usage and declarations across the repository.
 * Values are never read or stored.
 */
export async function analyzeEnvVars(
  repoPath: string,
  sourceFiles: string[],
): Promise<EnvVarInfo[]> {
  const defined = new Map<string, Set<string>>(); // name → files where defined
  const used = new Map<string, Set<string>>();     // name → files where used
  const defaults = new Set<string>();               // names with default values

  // ── Declared in .env files ──────────────────────────────────────────────────
  const envFiles = await fg([
    '.env.example', '.env.sample', '.env.template', '.env.defaults',
    'docker-compose.yml', 'docker-compose.yaml',
    '.github/workflows/*.yml', '.github/workflows/*.yaml',
  ], { cwd: repoPath, absolute: false, dot: true });

  for (const relPath of envFiles) {
    const content = readFileSafe(path.join(repoPath, relPath));
    if (!content) continue;

    if (relPath.endsWith('.yml') || relPath.endsWith('.yaml')) {
      // Extract `env:` sections from YAML (simple regex, not full YAML parse)
      const yamlEnvRe = /(?:^|\s{2,})([A-Z_][A-Z0-9_]*)\s*:/gm;
      let m: RegExpExecArray | null;
      while ((m = yamlEnvRe.exec(content)) !== null) {
        const name = m[1];
        if (!defined.has(name)) defined.set(name, new Set());
        defined.get(name)!.add(relPath);
      }
    } else {
      for (const name of parseEnvFile(content)) {
        if (!defined.has(name)) defined.set(name, new Set());
        defined.get(name)!.add(relPath);
        // If it has a default value (line has = something non-empty)
        const line = content.split('\n').find((l) => l.startsWith(`${name}=`));
        if (line && line.split('=')[1]?.trim()) defaults.add(name);
      }
    }
  }

  // ── Used in source files via process.env.NAME ──────────────────────────────
  for (const relPath of sourceFiles.slice(0, 200)) {
    const content = readFileSafe(path.join(repoPath, relPath));
    if (!content) continue;

    let m: RegExpExecArray | null;
    const re = new RegExp(ENV_USAGE_RE.source, 'g');
    while ((m = re.exec(content)) !== null) {
      const name = m[1];
      if (!used.has(name)) used.set(name, new Set());
      used.get(name)!.add(relPath);

      // Detect nullish coalescing default: process.env.FOO ?? 'default'
      const afterMatch = content.slice(m.index + m[0].length, m.index + m[0].length + 20);
      if (/^\s*(?:\?\?|[|][|])/.test(afterMatch)) defaults.add(name);
    }
  }

  // ── Merge ──────────────────────────────────────────────────────────────────
  const allNames = new Set([...defined.keys(), ...used.keys()]);
  const results: EnvVarInfo[] = [];

  for (const name of allNames) {
    results.push({
      name,
      definedIn: Array.from(defined.get(name) ?? []),
      usedIn: Array.from(used.get(name) ?? []),
      hasDefault: defaults.has(name),
      isSecret: isSecretName(name),
    });
  }

  return results.sort((a, b) => {
    // Surface secrets and missing vars first
    if (a.isSecret !== b.isSecret) return a.isSecret ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
}

// ─── Port analysis ────────────────────────────────────────────────────────────

const PORT_RE = /(?:port|PORT|listen|EXPOSE)\D{0,20}(\d{2,5})/gi;
const VALID_PORTS = { min: 80, max: 65535 };

/**
 * Find all port number mentions across config and source files.
 */
export async function analyzePortMentions(
  repoPath: string,
  filePaths: string[],
): Promise<PortMention[]> {
  const mentions: PortMention[] = [];
