+      symbols.push({
+        name,
+        kind: 'arrow_function',
+        filePath,
+        lineStart: decl.getStartLineNumber(),
+        lineEnd: decl.getEndLineNumber(),
+        isExported,
+        importance,
+        importanceReasons: reasons,
+        isAsync: init.getKind() === SyntaxKind.ArrowFunction
+          ? (init.asKind(SyntaxKind.ArrowFunction)?.isAsync() ?? false)
+          : false,
+        paramCount: params,
+      });
+    });
+  }
