  const allFiles = await fg('**', {
    cwd: repoPath,
    ignore: IGNORE_DIRS,
    absolute: false,
    followSymbolicLinks: false,
    dot: true,
  });

  return {
    name: pkg?.name ?? repoName(repoPath),
    description: pkg?.description,
    language,
    packageManager,
    framework,
    testFrameworks,
    nodeVersion,
    isMonorepo,
    workspaces,
    dependencies,
    devDependencies,
    scripts,
    isGitRepo,
    gitRemote,
    totalFiles: allFiles.length,
    sourceFiles: pureSourceFiles,
    testFiles: Array.from(testFilesNorm),
    configFiles,
    entryPoints,
    hasTypes,
  };
}

