import { resolveRepoPath } from '../utils/security';
import { analyzeRepository } from '../analyzers/repositoryAnalyzer';
import { analyzeCode } from '../analyzers/codeAnalyzer';
import { analyzeTests, analyzeEnvVars, analyzePortMentions } from '../analyzers/configAnalyzer';
import {
  createAnalysis,
  setStatus,
  setResult,
  setError,
} from '../models/analysisStore';
import type { AnalysisResult } from '../types';

/**
 * Kick off a full analysis of a repository.
 * This is intentionally async and fire-and-forget — the caller receives the
 * analysisId immediately and polls for status/result.
 */
export async function startAnalysis(rawPath: string): Promise<string> {
  // Validate path synchronously before creating the record
  const repoPath = resolveRepoPath(rawPath);

  const analysis = createAnalysis(repoPath);
  const id = analysis.id;

  // Run in background — do not await
  runAnalysis(id, repoPath).catch((err: unknown) => {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[devguard] Analysis ${id} failed:`, msg);
    setError(id, msg);
  });

  return id;
}

async function runAnalysis(id: string, repoPath: string): Promise<void> {
  setStatus(id, 'scanning');

  // ── 1. Repository profile ──────────────────────────────────────────────────
  const repositoryProfile = await analyzeRepository(repoPath);

  setStatus(id, 'analyzing');

  // ── 2. Code analysis (AST) — source files only ────────────────────────────
  const { symbols, routes } = analyzeCode(repoPath, repositoryProfile.sourceFiles);

  // ── 3. Test analysis ───────────────────────────────────────────────────────
  const testProfile = analyzeTests(repoPath, repositoryProfile.testFiles);

  // ── 4. Env var analysis ────────────────────────────────────────────────────
  const envVars = await analyzeEnvVars(repoPath, [
    ...repositoryProfile.sourceFiles,
    ...repositoryProfile.configFiles,
  ]);

  // ── 5. Port analysis ───────────────────────────────────────────────────────
  const portFiles = [
    ...repositoryProfile.sourceFiles,
    ...repositoryProfile.configFiles,
  ];
  const portMentions = await analyzePortMentions(repoPath, portFiles);

  const result: AnalysisResult = {
    analysisId: id,
    repositoryProfile,
    symbols,
    routes,
    testProfile: {
      ...testProfile,
      // Convert Set to Array for JSON serialization
      coveredFiles: testProfile.coveredFiles,
    },
    envVars,
    portMentions,
    scannedAt: new Date().toISOString(),
  };

  setResult(id, result);
}

