import { v4 as uuidv4 } from 'uuid';
import type {
  CodeSymbol,
  RouteInfo,
  TestProfile,
  TestMapping,
  TestGap,
  GeneratedTest,
  GapCategory,
  GapSeverity,
  CoverageStatus,
  TestFramework,
} from '../types';

// ─── Test Mapping ─────────────────────────────────────────────────────────────

/**
 * Map source files to their related test files using:
 * - filename proximity (foo.ts → foo.test.ts)
 * - import analysis (tests that import the source file)
 * - folder mirroring (src/services/foo.ts → tests/services/foo.test.ts)
 */
export function buildTestMappings(
  sourceFiles: string[],
  testProfile: TestProfile,
): TestMapping[] {
  const mappings: TestMapping[] = [];

  for (const sf of sourceFiles) {
    const relatedTests: string[] = [];
    let confidence = 0;

    const sfBase = sf.replace(/\.(ts|tsx|js|jsx)$/, '').replace(/\\/g, '/');
    const sfName = sfBase.split('/').pop() ?? '';

    for (const suite of testProfile.suites) {
      const suiteBase = suite.filePath.replace(/\.(ts|tsx|js|jsx)$/, '').replace(/\\/g, '/');

      // Direct name match: foo.ts ↔ foo.test.ts
      if (
        suiteBase.endsWith(`/${sfName}.test`) ||
        suiteBase.endsWith(`/${sfName}.spec`) ||
        suiteBase.endsWith(`/${sfName}`)
      ) {
        relatedTests.push(suite.filePath);
        confidence = Math.max(confidence, 0.95);
        continue;
      }

      // Import-based coverage
      if (suite.importsUnder.includes(sf)) {
        relatedTests.push(suite.filePath);
        confidence = Math.max(confidence, 0.8);
        continue;
      }

      // Path segment match: auth/user → user.test
      const sfSegments = sfBase.split('/');
      const suiteSegments = suiteBase.split('/');
      const overlap = sfSegments.filter((s) => suiteSegments.includes(s)).length;
      if (overlap >= 2 && sfName.length > 3) {
        relatedTests.push(suite.filePath);
        confidence = Math.max(confidence, 0.4);
      }
    }

    // De-duplicate
    const unique = [...new Set(relatedTests)];
    const status: CoverageStatus = unique.length === 0 ? 'none' : confidence >= 0.7 ? 'covered' : 'partial';

    mappings.push({
      sourceFile: sf,
      relatedTests: unique,
      coverageStatus: status,
      confidence: unique.length > 0 ? confidence : 0,
    });
  }

  return mappings;
}

// ─── Gap Detection ────────────────────────────────────────────────────────────

const AUTH_RE = /\b(auth|login|logout|register|signup|password|jwt|token|bearer|session|permission|role|guard|middleware|protect|authorize|authenticate)\b/i;
const DB_RE = /\b(create|update|delete|remove|save|insert|upsert|destroy|drop|truncate)\b/i;
const PAYMENT_RE = /\b(payment|stripe|paypal|checkout|charge|invoice|billing|subscription)\b/i;
const ERROR_HANDLING_RE = /\b(try|catch|throw|Error|reject|Promise\.reject|status\(4|status\(5)\b/;
const EDGE_CASE_RE = /\b(null|undefined|empty|zero|negative|invalid|missing|duplicate|overflow)\b/i;

function detectRecommendedTests(
  symbol: CodeSymbol,
  sourceContent: string,
  category: GapCategory,
): string[] {
  const name = symbol.name;
  const tests: string[] = [];

  switch (category) {
    case 'no_test':
      tests.push(`should execute ${name} successfully with valid input`);
      if (symbol.isAsync) tests.push(`should handle async rejection in ${name}`);
      if (symbol.paramCount > 0) tests.push(`should handle invalid parameters in ${name}`);
      if (AUTH_RE.test(sourceContent)) tests.push(`should reject unauthorized access in ${name}`);
      if (DB_RE.test(sourceContent)) tests.push(`should handle database errors in ${name}`);
      break;
    case 'missing_error_test':
      tests.push(`should return error when ${name} receives invalid input`);
      tests.push(`should handle exceptions thrown inside ${name}`);
      if (symbol.isAsync) tests.push(`should handle rejected promise in ${name}`);
      if (DB_RE.test(sourceContent)) tests.push(`should handle database failure in ${name}`);
      break;
    case 'missing_edge_case':
      tests.push(`should handle null/undefined input in ${name}`);
      tests.push(`should handle empty collection/string in ${name}`);
      tests.push(`should handle boundary values in ${name}`);
      break;
    case 'missing_auth_test':
      tests.push(`should reject unauthenticated request to ${name}`);
      tests.push(`should reject insufficient permissions in ${name}`);
      tests.push(`should prevent cross-user data access in ${name}`);
      break;
    case 'missing_integration_test':
      tests.push(`should integrate ${name} end-to-end with real dependencies`);
      tests.push(`should verify ${name} against the database`);
      break;
    case 'partial_test':
      tests.push(`should test failure path in ${name}`);
      tests.push(`should test edge cases in ${name}`);
      break;
  }

  return tests.slice(0, 4);
}

/**
 * Analyse symbols, routes, and test mappings to find testing gaps.
 * Returns concrete TestGap objects with evidence.
 */
export function findTestingGaps(
  symbols: CodeSymbol[],
  routes: RouteInfo[],
  mappings: TestMapping[],
  testProfile: TestProfile,
  sourceContents: Map<string, string>,
): TestGap[] {
  const gaps: TestGap[] = [];
  const mappingByFile = new Map<string, TestMapping>();
  for (const m of mappings) mappingByFile.set(m.sourceFile, m);

  // ── 1. Symbol-level gaps ──────────────────────────────────────────────────
  // Only check medium-importance and above to avoid noise
  const importantSymbols = symbols.filter(
    (s) => s.importance === 'critical' || s.importance === 'high' || s.importance === 'medium'
  );

  for (const sym of importantSymbols) {
    const mapping = mappingByFile.get(sym.filePath);
    const hasTests = mapping && mapping.relatedTests.length > 0;
    const content = sourceContents.get(sym.filePath) ?? '';

    // Determine gap category
    let category: GapCategory | null = null;
    let severity: GapSeverity = 'low';
    let reason = '';
    const evidence: string[] = [];

    if (!hasTests) {
      category = 'no_test';
      severity = sym.importance === 'critical' ? 'critical' : sym.importance === 'high' ? 'high' : 'medium';
      reason = `${sym.name} has importance "${sym.importance}" (${sym.importanceReasons.join(', ')}) but no test file appears to cover ${sym.filePath}`;
      evidence.push(`Symbol: ${sym.name} (${sym.kind}) at ${sym.filePath}:${sym.lineStart}`);
      evidence.push(`Importance signals: ${sym.importanceReasons.join(', ')}`);
    } else if (hasTests && ERROR_HANDLING_RE.test(content)) {
      // Has tests but likely missing error coverage
      const suite = testProfile.suites.find((s) => mapping!.relatedTests.includes(s.filePath));
      const allTestText = suite ? [...suite.itBlocks, ...suite.describeBlocks].join(' ').toLowerCase() : '';
      const hasErrorTest = /error|fail|reject|throw|invalid|exception/.test(allTestText);
      if (!hasErrorTest) {
        category = 'missing_error_test';
        severity = sym.importance === 'critical' ? 'high' : 'medium';
        reason = `${sym.name} contains error handling logic but no error-path tests were detected`;
        evidence.push(`Error handling found in ${sym.filePath}`);
        if (suite) evidence.push(`Existing test descriptions do not mention error/fail/reject`);
      }
    }

    // Auth gap: has auth logic, no auth test
    if (
      AUTH_RE.test(content) &&
      AUTH_RE.test(sym.name + sym.importanceReasons.join(' '))
    ) {
      const suite = testProfile.suites.find((s) => mapping?.relatedTests.includes(s.filePath));
      const allTestText = suite ? [...suite.itBlocks, ...suite.describeBlocks].join(' ').toLowerCase() : '';
      const hasAuthTest = /auth|unauthorized|forbidden|permission|role/.test(allTestText);
      if (!hasAuthTest) {
        // Only add auth gap if we haven't already added a no_test gap for this symbol
        if (category === null) {
          category = 'missing_auth_test';
          severity = 'high';
          reason = `${sym.name} involves authentication/authorization but no auth-related tests detected`;
          evidence.push(`Auth pattern found in ${sym.filePath}:${sym.lineStart}`);
        }
      }
    }

    if (!category) continue;

    const recommendedTests = detectRecommendedTests(sym, content, category);

    gaps.push({
      id: uuidv4(),
      severity,
      confidence: hasTests ? 0.7 : 0.85,
      category,
      title: `${category === 'no_test' ? 'No test for' : 'Incomplete tests for'}: ${sym.name}`,
      description: `The ${sym.kind} \`${sym.name}\` in \`${sym.filePath}\` ${category === 'no_test' ? 'has no automated test coverage' : 'has tests but is missing important test scenarios'}.`,
      filePath: sym.filePath,
      symbolName: sym.name,
      lineStart: sym.lineStart,
      reason,
      evidence,
      existingTests: mapping?.relatedTests ?? [],
      recommendedTests,
    });
  }

  // ── 2. Route-level gaps (API routes with no test) ─────────────────────────
  for (const route of routes) {
    const mapping = mappingByFile.get(route.filePath);
    if (mapping && mapping.relatedTests.length > 0) {
      // Check if any test mentions this route path
      const routePath = route.path.toLowerCase().replace(/[/:]/g, ' ');
      const covered = testProfile.suites.some((s) =>
        mapping.relatedTests.includes(s.filePath) &&
        [...s.itBlocks, ...s.describeBlocks].some((b) => {
          const norm = b.toLowerCase();
          return norm.includes(route.method.toLowerCase()) ||
            routePath.split(' ').filter(Boolean).some((seg) => norm.includes(seg));
        })
      );
      if (covered) continue;
    }

    // Route has no test coverage
    const isAuthRoute = AUTH_RE.test(route.path + (route.handlerName ?? ''));
    gaps.push({
      id: uuidv4(),
      severity: isAuthRoute ? 'critical' : 'high',
      confidence: 0.9,
      category: 'no_test',
      title: `API route not tested: ${route.method} ${route.path}`,
      description: `The API route \`${route.method} ${route.path}\` defined in \`${route.filePath}\` has no detected test coverage.`,
      filePath: route.filePath,
      symbolName: route.handlerName,
      lineStart: route.line,
      reason: `Route ${route.method} ${route.path} is a public API endpoint${isAuthRoute ? ' with auth logic' : ''} — untested routes are a reliability risk`,
      evidence: [`Route defined at ${route.filePath}:${route.line}`],
      existingTests: [],
      recommendedTests: [
        `should return 200 for valid ${route.method} ${route.path}`,
        `should return 4xx for invalid input to ${route.method} ${route.path}`,
        isAuthRoute ? `should return 401 for unauthenticated ${route.method} ${route.path}` : `should handle edge cases in ${route.method} ${route.path}`,
      ],
    });
  }

  // Sort: critical first, then by confidence desc
  return gaps
    .sort((a, b) => {
      const order = { critical: 0, high: 1, medium: 2, low: 3 };
      const so = order[a.severity] - order[b.severity];
      return so !== 0 ? so : b.confidence - a.confidence;
    })
    .slice(0, 40); // cap to avoid overwhelming the UI
}

// ─── Test Generation ──────────────────────────────────────────────────────────

function frameworkImports(fw: TestFramework): string {
  switch (fw) {
    case 'vitest': return `import { describe, it, expect, vi } from 'vitest';`;
    case 'jest':   return `import { describe, it, expect, jest } from '@jest/globals';`;
    case 'mocha':  return `import { describe, it } from 'mocha';\nimport assert from 'assert';`;
    default:       return `import { describe, it, expect } from '@jest/globals';`;
  }
}

/**
 * Generate a test file skeleton for a given gap.
 * Does not overwrite existing tests.
 */
export function generateTestForGap(
  gap: TestGap,
  framework: TestFramework,
  repoPath: string,
): GeneratedTest {
  const targetFile = gap.filePath;
  const symbolName = gap.symbolName ?? 'subject';
  const importPath = targetFile
    .replace(/\.(ts|tsx|js|jsx)$/, '')
    .replace(/^src\//, '../src/');

  const testFileName = targetFile
    .replace(/\.(ts|tsx|js|jsx)$/, '.test.ts')
    .replace(/^src\//, 'src/__tests__/')
    .replace(/^(?!src\/)/, 'src/__tests__/');

  const imports = frameworkImports(framework);
  const ext = framework === 'mocha' ? '' : '';

  const cases = gap.recommendedTests.map((t) => {
    if (framework === 'mocha') {
      return `  it('${t}', () => {\n    // TODO: implement\n    assert.ok(true);\n  });`;
    }
    return `  it('${t}', () => {\n    // TODO: implement\n    expect(true).toBe(true);\n  });`;
  }).join('\n\n');

  const content = `${imports}
import { ${symbolName} } from '${importPath}';

describe('${symbolName}', () => {
${cases}
});
`;

  return {
    gapId: gap.id,
    filePath: testFileName,
    content,
    targetFile,
    targetSymbol: gap.symbolName,
    framework,
  };
}

import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import fg from 'fast-glob';
import { readFileSafe, fileExists, isSecretName } from '../utils/security';
import type {
  RepositoryProfile,
  ConfigHealth,
  ConfigIssue,
  EnvVarInfo,
  PortMention,
  IssueSeverity,
  IssueCategory,
} from '../types';

// ─── Helpers ──────────────────────────────────────────────────────────────────

function issue(
  severity: IssueSeverity,
  confidence: number,
  category: IssueCategory,
  title: string,
  description: string,
  recommendedFix: string,
  extras: Partial<ConfigIssue> = {},
): ConfigIssue {
  return {
    id: uuidv4(),
    severity,
    confidence,
    category,
    title,
    description,
    evidence: [],
    recommendedFix,
    ...extras,
  };
}

// ─── ENV var analysis ─────────────────────────────────────────────────────────

const ENV_USAGE_RE = /process\.env\.([A-Z_][A-Z0-9_]*)/g;
const ENV_DEFINE_NAME_RE = /^([A-Z_][A-Z0-9_]*)(?:\s*=.*)?$/;

function parseEnvNames(content: string): string[] {
  return content
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#'))
    .map((l) => {
      const m = ENV_DEFINE_NAME_RE.exec(l);
      return m ? m[1] : null;
    })
    .filter((n): n is string => n !== null);
}

export async function analyzeEnvVars(
  repoPath: string,
  sourceFiles: string[],
): Promise<{ envVars: EnvVarInfo[]; issues: ConfigIssue[] }> {
  const defined = new Map<string, Set<string>>();
  const used = new Map<string, Set<string>>();
  const defaults = new Set<string>();

  const envFiles = await fg(
    ['.env.example', '.env.sample', '.env.template', '.env.defaults'],
    { cwd: repoPath, absolute: false, dot: true }
  );

  for (const relPath of envFiles) {
    const content = readFileSafe(path.join(repoPath, relPath));
    if (!content) continue;
    for (const name of parseEnvNames(content)) {
      if (!defined.has(name)) defined.set(name, new Set());
      defined.get(name)!.add(relPath);
      const line = content.split('\n').find((l) => l.startsWith(`${name}=`));
      if (line && line.split('=').slice(1).join('=').trim()) defaults.add(name);
    }
  }

  for (const relPath of sourceFiles.slice(0, 300)) {
    const content = readFileSafe(path.join(repoPath, relPath));
    if (!content) continue;
    const re = new RegExp(ENV_USAGE_RE.source, 'g');
    let m: RegExpExecArray | null;
    while ((m = re.exec(content)) !== null) {
      const name = m[1];
      if (!used.has(name)) used.set(name, new Set());
      used.get(name)!.add(relPath);
      const after = content.slice(m.index + m[0].length, m.index + m[0].length + 25);
      if (/^\s*(?:\?\?|[|][|])/.test(after)) defaults.add(name);
    }
  }

  const allNames = new Set([...defined.keys(), ...used.keys()]);
  const envVars: EnvVarInfo[] = [];
  const issues: ConfigIssue[] = [];

  for (const name of allNames) {
    const def = Array.from(defined.get(name) ?? []);
    const usedIn = Array.from(used.get(name) ?? []);
    const secret = isSecretName(name);

    envVars.push({
      name,
      definedIn: def,
      usedIn,
      hasDefault: defaults.has(name),
      isSecret: secret,
    });

    // Issue: used but not documented
    if (usedIn.length > 0 && def.length === 0 && !defaults.has(name)) {
      issues.push(issue(
        secret ? 'high' : 'medium',
        0.85,
        'environment',
        `Undocumented environment variable: ${name}`,
        `\`${name}\` is referenced in source code but not defined in any .env.example or .env.template file.`,
        `Add \`${name}=${secret ? '<secret>' : '<value>'}\` to your .env.example file.`,
        { evidence: [`Used in: ${usedIn.slice(0, 3).join(', ')}`] },
      ));
    }
  }

  return { envVars: envVars.sort((a, b) => a.name.localeCompare(b.name)), issues };
}

// ─── Port analysis ────────────────────────────────────────────────────────────

const PORT_RE = /(?:port|PORT|listen|EXPOSE)\D{0,20}(\d{2,5})/gi;
const PORT_RANGE = { min: 80, max: 65535 };

export async function analyzePortsAndDocker(
  repoPath: string,
  profile: RepositoryProfile,
): Promise<{ portMentions: PortMention[]; issues: ConfigIssue[]; dockerfiles: string[] }> {
  const mentions: PortMention[] = [];
  const issues: ConfigIssue[] = [];
  const seen = new Set<string>();

  const filesToScan = [
    ...profile.sourceFiles,
    ...profile.configFiles,
  ].slice(0, 150);

  for (const relPath of filesToScan) {
    const content = readFileSafe(path.join(repoPath, relPath));
    if (!content) continue;
    const lines = content.split('\n');
    lines.forEach((line, idx) => {
      const re = new RegExp(PORT_RE.source, 'gi');
      let m: RegExpExecArray | null;
      while ((m = re.exec(line)) !== null) {
        const port = parseInt(m[1], 10);
        if (port < PORT_RANGE.min || port > PORT_RANGE.max) continue;
        const key = `${relPath}:${port}`;
        if (seen.has(key)) return;
        seen.add(key);
        mentions.push({ port, filePath: relPath, context: line.trim().slice(0, 80), line: idx + 1 });
      }
    });
  }

  // Detect port conflicts
  const portsByFile = new Map<number, string[]>();
  for (const m of mentions) {
    if (!portsByFile.has(m.port)) portsByFile.set(m.port, []);
    portsByFile.get(m.port)!.push(m.filePath);
  }

  // Multiple different ports across source/docker/readme = possible mismatch
  const allPorts = Array.from(portsByFile.keys());
  const appPorts = mentions.filter((m) => /\.(ts|js)$/.test(m.filePath)).map((m) => m.port);
  const dockerPorts = mentions.filter((m) => /dockerfile|docker-compose/i.test(m.filePath)).map((m) => m.port);

  const appPortSet = new Set(appPorts);
  const dockerPortSet = new Set(dockerPorts);
  const mismatchedPorts = Array.from(appPortSet).filter((p) => dockerPortSet.size > 0 && !dockerPortSet.has(p));

  if (mismatchedPorts.length > 0) {
    issues.push(issue(
      'medium', 0.75, 'ports',
      `Port mismatch between application and Docker`,
      `Application code uses port(s) ${[...appPortSet].join(', ')} but Docker configuration uses port(s) ${[...dockerPortSet].join(', ')}.`,
      `Align port configuration across application code, Docker, and environment variables.`,
      { evidence: mismatchedPorts.map((p) => `Port ${p} in app but not in Docker`) },
    ));
  }

  // Docker-specific checks
  const dockerfiles = profile.configFiles.filter((f) =>
    /dockerfile$/i.test(f) || /docker-compose\.(yml|yaml)$/.test(f)
  );

  for (const df of dockerfiles) {
    const content = readFileSafe(path.join(repoPath, df));
    if (!content) continue;

    // Check: Dockerfile uses npm ci vs npm install
    if (/dockerfile$/i.test(df)) {
      if (!content.includes('npm ci') && content.includes('npm install') && !content.includes('--production')) {
        issues.push(issue(
          'low', 0.7, 'docker',
          `Docker uses \`npm install\` instead of \`npm ci\``,
          `In \`${df}\`, using \`npm install\` in production Docker images can produce non-deterministic builds. Prefer \`npm ci\`.`,
          `Replace \`npm install\` with \`npm ci\` in your Dockerfile.`,
          { filePath: df, evidence: ['npm install detected in Dockerfile'] },
        ));
      }

      // Check: running as root
      if (!content.includes('USER ') || /USER\s+root/.test(content)) {
        issues.push(issue(
          'medium', 0.8, 'docker',
          `Docker container may run as root`,
          `No non-root USER directive found in \`${df}\`. Running containers as root is a security risk.`,
          `Add \`USER node\` (or another non-root user) before the CMD/ENTRYPOINT in your Dockerfile.`,
          { filePath: df, evidence: ['No USER directive found'] },
        ));
      }
    }
  }

  return { portMentions: mentions, issues, dockerfiles };
}

// ─── CI analysis ──────────────────────────────────────────────────────────────

export async function analyzeCi(
  repoPath: string,
  profile: RepositoryProfile,
): Promise<{ issues: ConfigIssue[]; ciFiles: string[] }> {
  const issues: ConfigIssue[] = [];
  const ciFiles = profile.configFiles.filter((f) =>
    f.includes('.github/workflows') || f.endsWith('.gitlab-ci.yml') || f.includes('.circleci/')
  );

  for (const ciFile of ciFiles) {
    const content = readFileSafe(path.join(repoPath, ciFile));
    if (!content) continue;

    // Node version specified in CI?
    const nodeVersionMatch = content.match(/node-version[:\s]+['"]?(\d+[.\d]*)/i);
    if (!nodeVersionMatch && profile.nodeVersion) {
      issues.push(issue(
        'low', 0.7, 'ci',
        `CI workflow does not pin a Node.js version`,
        `\`${ciFile}\` does not specify a Node.js version. Without pinning, CI may behave differently from local development.`,
        `Add \`node-version: '${profile.nodeVersion ?? '20'}'\` to your workflow's setup-node step.`,
        { filePath: ciFile },
      ));
    }

    // Does CI install dependencies?
    if (!/npm (ci|install)|yarn install|pnpm install/.test(content)) {
      issues.push(issue(
        'high', 0.9, 'ci',
        `CI workflow may not install dependencies`,
        `\`${ciFile}\` does not appear to run a dependency install command.`,
        `Add \`run: npm ci\` (or equivalent) to your CI workflow.`,
        { filePath: ciFile, evidence: ['No npm/yarn/pnpm install found in workflow'] },
      ));
    }

    // Does CI run tests?
    const testScriptNames = Object.keys(profile.scripts).filter((k) => k === 'test' || k.startsWith('test'));
    const hasTestInCi = /npm (run )?test|yarn test|pnpm test|vitest|jest|mocha/.test(content);
    if (!hasTestInCi && testScriptNames.length > 0) {
      issues.push(issue(
        'high', 0.85, 'ci',
        `CI workflow does not run tests`,
        `\`${ciFile}\` does not appear to run the test suite, but the project has a test script defined.`,
        `Add a step that runs \`npm test\` (or equivalent) in your CI workflow.`,
        { filePath: ciFile, evidence: [`Test script exists: ${testScriptNames.join(', ')}`] },
      ));
    }
  }

  return { issues, ciFiles };
}

// ─── Documentation analysis ───────────────────────────────────────────────────

export function analyzeDocumentation(
  repoPath: string,
  profile: RepositoryProfile,
): ConfigIssue[] {
  const issues: ConfigIssue[] = [];
  const readmeFile = profile.configFiles.find((f) => /readme\.md$/i.test(f));
  if (!readmeFile) {
    issues.push(issue(
      'low', 1.0, 'documentation',
      'No README.md found',
      'The repository does not have a README.md file. This makes it difficult for new contributors to understand the project.',
      'Create a README.md with setup instructions, run commands, and test commands.',
    ));
    return issues;
  }

  const content = readFileSafe(path.join(repoPath, readmeFile)) ?? '';
  const lower = content.toLowerCase();

  // Check if README mentions install
  if (!lower.includes('npm install') && !lower.includes('yarn install') && !lower.includes('pnpm install')) {
    issues.push(issue(
      'info', 0.8, 'documentation',
      'README does not document how to install dependencies',
      `\`${readmeFile}\` does not include dependency installation instructions.`,
      'Add installation instructions (e.g., `npm install`) to your README.',
      { filePath: readmeFile },
    ));
  }

  // Check if README mentions test command
  const hasTestScript = Object.keys(profile.scripts).some((k) => k === 'test');
  if (hasTestScript && !lower.includes('npm test') && !lower.includes('npm run test') && !lower.includes('yarn test')) {
    issues.push(issue(
      'info', 0.75, 'documentation',
      'README does not document how to run tests',
      `\`${readmeFile}\` does not mention the test command despite a test script being defined.`,
      'Add test instructions (e.g., `npm test`) to your README.',
      { filePath: readmeFile },
    ));
  }

  // Check: README mentions a port that doesn't match code
  const readmePorts = new Set<number>();
  const portRe = /(?:port|localhost)[:\s]+(\d{2,5})/gi;
  let m: RegExpExecArray | null;
  while ((m = portRe.exec(content)) !== null) {
    const p = parseInt(m[1], 10);
    if (p >= 80 && p <= 65535) readmePorts.add(p);
  }

  return issues;
}

// ─── Runtime / package analysis ───────────────────────────────────────────────

export function analyzeRuntime(
  repoPath: string,
  profile: RepositoryProfile,
): ConfigIssue[] {
  const issues: ConfigIssue[] = [];

  // Missing test script
  if (!profile.scripts['test']) {
    issues.push(issue(
      'medium', 0.95, 'scripts',
      'No "test" script defined in package.json',
      'The project does not have a `test` script in package.json. Running `npm test` will fail.',
      'Add a `"test"` script to package.json (e.g., `"test": "jest"` or `"test": "vitest run"`).',
      { filePath: 'package.json' },
    ));
  }

  // Has test framework in devDeps but no test script
  const hasTestFrameworkDep = ['jest', 'vitest', 'mocha'].some(
    (fw) => profile.devDependencies[fw]
  );
  if (hasTestFrameworkDep && !profile.scripts['test']) {
    issues.push(issue(
      'medium', 0.9, 'scripts',
      'Test framework installed but no test script configured',
      'A test framework is listed in devDependencies but no `test` script is defined.',
      'Configure the test script in package.json to use the installed framework.',
      { filePath: 'package.json', evidence: ['Test framework in devDependencies but no test script'] },
    ));
  }

  // .env.example exists check
  const hasEnvExample = fileExists(path.join(repoPath, '.env.example')) ||
    fileExists(path.join(repoPath, '.env.sample'));

  const usesEnv = profile.sourceFiles.length > 0; // simplified check — full check is done in env analysis
  if (!hasEnvExample && usesEnv) {
    issues.push(issue(
      'low', 0.7, 'environment',
      'No .env.example file found',
      'The project does not have a .env.example file. New contributors will not know which environment variables are required.',
      'Create a .env.example file documenting all required environment variables (with placeholder values, not real secrets).',
    ));
  }

  return issues;
}

// ─── Full ConfigDoctor ────────────────────────────────────────────────────────

export async function runConfigDoctor(
  repoPath: string,
  profile: RepositoryProfile,
): Promise<ConfigHealth> {
  const allFiles = [...profile.sourceFiles, ...profile.configFiles];

  const [envResult, portResult, ciResult] = await Promise.all([
    analyzeEnvVars(repoPath, allFiles),
    analyzePortsAndDocker(repoPath, profile),
    analyzeCi(repoPath, profile),
  ]);

  const docIssues = analyzeDocumentation(repoPath, profile);
  const runtimeIssues = analyzeRuntime(repoPath, profile);

  const allIssues: ConfigIssue[] = [
    ...envResult.issues,
    ...portResult.issues,
    ...ciResult.issues,
    ...docIssues,
    ...runtimeIssues,
  ];

  // Sort: critical first
  const severityOrder = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };
  allIssues.sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity]);

  const criticalCount = allIssues.filter((i) => i.severity === 'critical').length;
  const highCount = allIssues.filter((i) => i.severity === 'high').length;

  const summary = allIssues.length === 0
    ? 'No configuration issues detected.'
    : `Found ${allIssues.length} issue(s): ${criticalCount} critical, ${highCount} high.`;

  return {
    issues: allIssues,
    envVars: envResult.envVars,
    portMentions: portResult.portMentions,
    dockerfiles: portResult.dockerfiles,
    ciFiles: ciResult.ciFiles,
    hasEnvExample: fileExists(path.join(repoPath, '.env.example')) || fileExists(path.join(repoPath, '.env.sample')),
    hasDotenv: profile.devDependencies['dotenv'] !== undefined || profile.dependencies['dotenv'] !== undefined,
    summary,
  };
}

import { v4 as uuidv4 } from 'uuid';
import type {
  CodeSymbol,
  RouteInfo,
  TestProfile,
  TestMapping,
  TestGap,
  GeneratedTest,
  GapCategory,
  GapSeverity,
  CoverageStatus,
  TestFramework,
} from '../types';

// ─── Test Mapping ─────────────────────────────────────────────────────────────

/**
 * Map source files to their related test files using:
 * - filename proximity (foo.ts → foo.test.ts)
 * - import analysis (tests that import the source file)
 * - folder mirroring (src/services/foo.ts → tests/services/foo.test.ts)
 */
export function buildTestMappings(
  sourceFiles: string[],
  testProfile: TestProfile,
): TestMapping[] {
  const mappings: TestMapping[] = [];

  for (const sf of sourceFiles) {
    const relatedTests: string[] = [];
    let confidence = 0;

    const sfBase = sf.replace(/\.(ts|tsx|js|jsx)$/, '').replace(/\\/g, '/');
    const sfName = sfBase.split('/').pop() ?? '';

    for (const suite of testProfile.suites) {
      const suiteBase = suite.filePath.replace(/\.(ts|tsx|js|jsx)$/, '').replace(/\\/g, '/');

      // Direct name match: foo.ts ↔ foo.test.ts
      if (
        suiteBase.endsWith(`/${sfName}.test`) ||
        suiteBase.endsWith(`/${sfName}.spec`) ||
        suiteBase.endsWith(`/${sfName}`)
      ) {
        relatedTests.push(suite.filePath);
        confidence = Math.max(confidence, 0.95);
        continue;
      }

      // Import-based coverage
      if (suite.importsUnder.includes(sf)) {
        relatedTests.push(suite.filePath);
        confidence = Math.max(confidence, 0.8);
        continue;
      }

      // Path segment match: auth/user → user.test
      const sfSegments = sfBase.split('/');
      const suiteSegments = suiteBase.split('/');
      const overlap = sfSegments.filter((s) => suiteSegments.includes(s)).length;
      if (overlap >= 2 && sfName.length > 3) {
        relatedTests.push(suite.filePath);
        confidence = Math.max(confidence, 0.4);
      }
    }

    // De-duplicate
    const unique = [...new Set(relatedTests)];
    const status: CoverageStatus = unique.length === 0 ? 'none' : confidence >= 0.7 ? 'covered' : 'partial';

    mappings.push({
      sourceFile: sf,
      relatedTests: unique,
      coverageStatus: status,
      confidence: unique.length > 0 ? confidence : 0,
    });
  }

  return mappings;
}

// ─── Gap Detection ────────────────────────────────────────────────────────────

const AUTH_RE = /\b(auth|login|logout|register|signup|password|jwt|token|bearer|session|permission|role|guard|middleware|protect|authorize|authenticate)\b/i;
const DB_RE = /\b(create|update|delete|remove|save|insert|upsert|destroy|drop|truncate)\b/i;
const PAYMENT_RE = /\b(payment|stripe|paypal|checkout|charge|invoice|billing|subscription)\b/i;
const ERROR_HANDLING_RE = /\b(try|catch|throw|Error|reject|Promise\.reject|status\(4|status\(5)\b/;
const EDGE_CASE_RE = /\b(null|undefined|empty|zero|negative|invalid|missing|duplicate|overflow)\b/i;

function detectRecommendedTests(
  symbol: CodeSymbol,
  sourceContent: string,
  category: GapCategory,
): string[] {
  const name = symbol.name;
  const tests: string[] = [];

  switch (category) {
    case 'no_test':
      tests.push(`should execute ${name} successfully with valid input`);
      if (symbol.isAsync) tests.push(`should handle async rejection in ${name}`);
      if (symbol.paramCount > 0) tests.push(`should handle invalid parameters in ${name}`);
      if (AUTH_RE.test(sourceContent)) tests.push(`should reject unauthorized access in ${name}`);
      if (DB_RE.test(sourceContent)) tests.push(`should handle database errors in ${name}`);
      break;
    case 'missing_error_test':
      tests.push(`should return error when ${name} receives invalid input`);
      tests.push(`should handle exceptions thrown inside ${name}`);
      if (symbol.isAsync) tests.push(`should handle rejected promise in ${name}`);
      if (DB_RE.test(sourceContent)) tests.push(`should handle database failure in ${name}`);
      break;
    case 'missing_edge_case':
      tests.push(`should handle null/undefined input in ${name}`);
      tests.push(`should handle empty collection/string in ${name}`);
      tests.push(`should handle boundary values in ${name}`);
      break;
    case 'missing_auth_test':
      tests.push(`should reject unauthenticated request to ${name}`);
      tests.push(`should reject insufficient permissions in ${name}`);
      tests.push(`should prevent cross-user data access in ${name}`);
      break;
    case 'missing_integration_test':
      tests.push(`should integrate ${name} end-to-end with real dependencies`);
      tests.push(`should verify ${name} against the database`);
      break;
    case 'partial_test':
      tests.push(`should test failure path in ${name}`);
      tests.push(`should test edge cases in ${name}`);
      break;
  }

  return tests.slice(0, 4);
}

/**
 * Analyse symbols, routes, and test mappings to find testing gaps.
 * Returns concrete TestGap objects with evidence.
 */
export function findTestingGaps(
  symbols: CodeSymbol[],
  routes: RouteInfo[],
  mappings: TestMapping[],
  testProfile: TestProfile,
  sourceContents: Map<string, string>,
): TestGap[] {
  const gaps: TestGap[] = [];
  const mappingByFile = new Map<string, TestMapping>();
  for (const m of mappings) mappingByFile.set(m.sourceFile, m);

  // ── 1. Symbol-level gaps ──────────────────────────────────────────────────
  // Only check medium-importance and above to avoid noise
  const importantSymbols = symbols.filter(
    (s) => s.importance === 'critical' || s.importance === 'high' || s.importance === 'medium'
  );

  for (const sym of importantSymbols) {
    const mapping = mappingByFile.get(sym.filePath);
    const hasTests = mapping && mapping.relatedTests.length > 0;
    const content = sourceContents.get(sym.filePath) ?? '';

    // Determine gap category
    let category: GapCategory | null = null;
    let severity: GapSeverity = 'low';
    let reason = '';
    const evidence: string[] = [];

    if (!hasTests) {
      category = 'no_test';
      severity = sym.importance === 'critical' ? 'critical' : sym.importance === 'high' ? 'high' : 'medium';
      reason = `${sym.name} has importance "${sym.importance}" (${sym.importanceReasons.join(', ')}) but no test file appears to cover ${sym.filePath}`;
      evidence.push(`Symbol: ${sym.name} (${sym.kind}) at ${sym.filePath}:${sym.lineStart}`);
      evidence.push(`Importance signals: ${sym.importanceReasons.join(', ')}`);
    } else if (hasTests && ERROR_HANDLING_RE.test(content)) {
      // Has tests but likely missing error coverage
      const suite = testProfile.suites.find((s) => mapping!.relatedTests.includes(s.filePath));
      const allTestText = suite ? [...suite.itBlocks, ...suite.describeBlocks].join(' ').toLowerCase() : '';
      const hasErrorTest = /error|fail|reject|throw|invalid|exception/.test(allTestText);
      if (!hasErrorTest) {
        category = 'missing_error_test';
        severity = sym.importance === 'critical' ? 'high' : 'medium';
        reason = `${sym.name} contains error handling logic but no error-path tests were detected`;
        evidence.push(`Error handling found in ${sym.filePath}`);
        if (suite) evidence.push(`Existing test descriptions do not mention error/fail/reject`);
      }
    }

    // Auth gap: has auth logic, no auth test
    if (
      AUTH_RE.test(content) &&
      AUTH_RE.test(sym.name + sym.importanceReasons.join(' '))
    ) {
      const suite = testProfile.suites.find((s) => mapping?.relatedTests.includes(s.filePath));
      const allTestText = suite ? [...suite.itBlocks, ...suite.describeBlocks].join(' ').toLowerCase() : '';
      const hasAuthTest = /auth|unauthorized|forbidden|permission|role/.test(allTestText);
      if (!hasAuthTest) {
        // Only add auth gap if we haven't already added a no_test gap for this symbol
        if (category === null) {
          category = 'missing_auth_test';
          severity = 'high';
          reason = `${sym.name} involves authentication/authorization but no auth-related tests detected`;
          evidence.push(`Auth pattern found in ${sym.filePath}:${sym.lineStart}`);
        }
      }
    }

    if (!category) continue;

    const recommendedTests = detectRecommendedTests(sym, content, category);

    gaps.push({
      id: uuidv4(),
      severity,
      confidence: hasTests ? 0.7 : 0.85,
      category,
      title: `${category === 'no_test' ? 'No test for' : 'Incomplete tests for'}: ${sym.name}`,
      description: `The ${sym.kind} \`${sym.name}\` in \`${sym.filePath}\` ${category === 'no_test' ? 'has no automated test coverage' : 'has tests but is missing important test scenarios'}.`,
      filePath: sym.filePath,
      symbolName: sym.name,
      lineStart: sym.lineStart,
      reason,
      evidence,
      existingTests: mapping?.relatedTests ?? [],
      recommendedTests,
    });
  }

  // ── 2. Route-level gaps (API routes with no test) ─────────────────────────
  for (const route of routes) {
    const mapping = mappingByFile.get(route.filePath);
    if (mapping && mapping.relatedTests.length > 0) {
      // Check if any test mentions this route path
      const routePath = route.path.toLowerCase().replace(/[/:]/g, ' ');
      const covered = testProfile.suites.some((s) =>
        mapping.relatedTests.includes(s.filePath) &&
        [...s.itBlocks, ...s.describeBlocks].some((b) => {
          const norm = b.toLowerCase();
          return norm.includes(route.method.toLowerCase()) ||
            routePath.split(' ').filter(Boolean).some((seg) => norm.includes(seg));
        })
      );
      if (covered) continue;
    }

    // Route has no test coverage
    const isAuthRoute = AUTH_RE.test(route.path + (route.handlerName ?? ''));
    gaps.push({
      id: uuidv4(),
      severity: isAuthRoute ? 'critical' : 'high',
      confidence: 0.9,
      category: 'no_test',
      title: `API route not tested: ${route.method} ${route.path}`,
      description: `The API route \`${route.method} ${route.path}\` defined in \`${route.filePath}\` has no detected test coverage.`,
      filePath: route.filePath,
      symbolName: route.handlerName,
      lineStart: route.line,
      reason: `Route ${route.method} ${route.path} is a public API endpoint${isAuthRoute ? ' with auth logic' : ''} — untested routes are a reliability risk`,
      evidence: [`Route defined at ${route.filePath}:${route.line}`],
      existingTests: [],
      recommendedTests: [
        `should return 200 for valid ${route.method} ${route.path}`,
        `should return 4xx for invalid input to ${route.method} ${route.path}`,
        isAuthRoute ? `should return 401 for unauthenticated ${route.method} ${route.path}` : `should handle edge cases in ${route.method} ${route.path}`,
      ],
    });
  }

  // Sort: critical first, then by confidence desc
  return gaps
    .sort((a, b) => {
      const order = { critical: 0, high: 1, medium: 2, low: 3 };
      const so = order[a.severity] - order[b.severity];
      return so !== 0 ? so : b.confidence - a.confidence;
    })
    .slice(0, 40); // cap to avoid overwhelming the UI
}

// ─── Test Generation ──────────────────────────────────────────────────────────

function frameworkImports(fw: TestFramework): string {
  switch (fw) {
    case 'vitest': return `import { describe, it, expect, vi } from 'vitest';`;
    case 'jest':   return `import { describe, it, expect, jest } from '@jest/globals';`;
    case 'mocha':  return `import { describe, it } from 'mocha';\nimport assert from 'assert';`;
    default:       return `import { describe, it, expect } from '@jest/globals';`;
  }
}

/**
 * Generate a test file skeleton for a given gap.
 * Does not overwrite existing tests.
 */
export function generateTestForGap(
  gap: TestGap,
  framework: TestFramework,
  repoPath: string,
): GeneratedTest {
  const targetFile = gap.filePath;
  const symbolName = gap.symbolName ?? 'subject';
  const importPath = targetFile
    .replace(/\.(ts|tsx|js|jsx)$/, '')
    .replace(/^src\//, '../src/');

  const testFileName = targetFile
    .replace(/\.(ts|tsx|js|jsx)$/, '.test.ts')
    .replace(/^src\//, 'src/__tests__/')
    .replace(/^(?!src\/)/, 'src/__tests__/');

  const imports = frameworkImports(framework);
  const ext = framework === 'mocha' ? '' : '';

  const cases = gap.recommendedTests.map((t) => {
    if (framework === 'mocha') {
      return `  it('${t}', () => {\n    // TODO: implement\n    assert.ok(true);\n  });`;
    }
    return `  it('${t}', () => {\n    // TODO: implement\n    expect(true).toBe(true);\n  });`;
  }).join('\n\n');

  const content = `${imports}
import { ${symbolName} } from '${importPath}';

describe('${symbolName}', () => {
${cases}
});
`;

  return {
    gapId: gap.id,
    filePath: testFileName,
    content,
    targetFile,
    targetSymbol: gap.symbolName,
    framework,
  };
}

