            {topRisks.map((risk) => (
              <div
                key={risk.id}
                className="card flex items-start gap-4"
              >
                <div className="mt-0.5">
                  <span className={severityBadgeClass(risk.level)}>
                    {risk.level.toUpperCase()}
                  </span>
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-200 mb-1">{risk.title}</p>
