const express = require('express');
const authRouter = require('./routes/auth');
const tasksRouter = require('./routes/tasks');

const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.json());

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.use('/api/auth', authRouter);
app.use('/api/tasks', tasksRouter);

// Error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Task API running on port ${PORT}`);
  });
}

module.exports = app;

const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const router = express.Router();

// In-memory user store (demo only)
const users = [];

/**
 * Register a new user.
 * POST /api/auth/register
 */
router.post('/register', async (req, res) => {
  const { username, password, email } = req.body;

  if (!username || !password || !email) {
    return res.status(400).json({ error: 'username, password, and email are required' });
  }

  if (users.find(u => u.username === username)) {
    return res.status(409).json({ error: 'Username already taken' });
  }

  const hashed = await bcrypt.hash(password, 10);
  const user = { id: Date.now().toString(), username, email, password: hashed, role: 'user' };
  users.push(user);

  res.status(201).json({ id: user.id, username, email });
});

/**
 * Login with username and password.
 * POST /api/auth/login
 */
router.post('/login', async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'username and password are required' });
  }

  const user = users.find(u => u.username === username);
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const valid = await bcrypt.compare(password, user.password);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = jwt.sign(
    { userId: user.id, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '24h' }
  );

  res.json({ token, userId: user.id });
});

/**
 * Get current user profile.
 * GET /api/auth/me
 */
router.get('/me', requireAuth, (req, res) => {
  const user = users.find(u => u.id === req.userId);
  if (!user) return res.status(404).json({ error: 'User not found' });
  const { password, ...safe } = user;
  res.json(safe);
});

/**
 * Middleware: verify JWT token.
 */
function requireAuth(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth || !auth.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(auth.slice(7), process.env.JWT_SECRET);
    req.userId = decoded.userId;
    req.userRole = decoded.role;
    next();
  } catch {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
}

module.exports = router;
module.exports.requireAuth = requireAuth;

const express = require('express');
const { requireAuth } = require('./auth');
const router = express.Router();

// In-memory task store (demo only)
const tasks = [];

/**
 * Get all tasks for the authenticated user.
 * GET /api/tasks
 */
router.get('/', requireAuth, (req, res) => {
  const userTasks = tasks.filter(t => t.userId === req.userId);
  res.json(userTasks);
});

/**
 * Create a new task.
 * POST /api/tasks
 */
router.post('/', requireAuth, (req, res) => {
  const { title, description, dueDate } = req.body;

  if (!title) {
    return res.status(400).json({ error: 'title is required' });
  }

  const task = {
    id: Date.now().toString(),
    userId: req.userId,
    title,
    description: description ?? '',
    dueDate: dueDate ?? null,
    completed: false,
    createdAt: new Date().toISOString(),
  };

  tasks.push(task);
  res.status(201).json(task);
});

/**
 * Update a task.
 * PUT /api/tasks/:id
 */
router.put('/:id', requireAuth, (req, res) => {
  const task = tasks.find(t => t.id === req.params.id);

  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }

  // Authorization: only owner can modify
  if (task.userId !== req.userId) {
    return res.status(403).json({ error: 'Forbidden: you do not own this task' });
  }

  const { title, description, dueDate, completed } = req.body;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;
  if (dueDate !== undefined) task.dueDate = dueDate;
  if (completed !== undefined) task.completed = completed;

  res.json(task);
});

/**
 * Delete a task.
 * DELETE /api/tasks/:id
 */
router.delete('/:id', requireAuth, (req, res) => {
  const idx = tasks.findIndex(t => t.id === req.params.id);

  if (idx === -1) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const task = tasks[idx];
  if (task.userId !== req.userId) {
    return res.status(403).json({ error: 'Forbidden: you do not own this task' });
  }

  tasks.splice(idx, 1);
  res.status(204).send();
});

/**
 * Mark a task as complete.
 * PATCH /api/tasks/:id/complete
 */
router.patch('/:id/complete', requireAuth, (req, res) => {
  const task = tasks.find(t => t.id === req.params.id);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  if (task.userId !== req.userId) return res.status(403).json({ error: 'Forbidden' });
  task.completed = true;
  res.json(task);
});

module.exports = router;

/**
 * Task service — business logic layer for task operations.
 * Routes delegate to this service.
 */

function validateTaskInput({ title, dueDate }) {
  if (!title || typeof title !== 'string' || title.trim().length === 0) {
    return { valid: false, error: 'title must be a non-empty string' };
  }
  if (dueDate && isNaN(Date.parse(dueDate))) {
    return { valid: false, error: 'dueDate must be a valid ISO date string' };
  }
  return { valid: true };
}

function sortTasks(tasks, sortBy = 'createdAt') {
  return [...tasks].sort((a, b) => {
    if (sortBy === 'dueDate') {
      if (!a.dueDate) return 1;
      if (!b.dueDate) return -1;
      return new Date(a.dueDate) - new Date(b.dueDate);
    }
    return new Date(b.createdAt) - new Date(a.createdAt);
  });
}

function filterByStatus(tasks, status) {
  if (status === 'completed') return tasks.filter(t => t.completed);
  if (status === 'pending')   return tasks.filter(t => !t.completed);
  return tasks;
}

function getOverdueTasks(tasks) {
  const now = new Date();
  return tasks.filter(t => !t.completed && t.dueDate && new Date(t.dueDate) < now);
}

module.exports = { validateTaskInput, sortTasks, filterByStatus, getOverdueTasks };

const { validateTaskInput } = require('../services/taskService');

describe('validateTaskInput', () => {
  it('should return valid for a correct task', () => {
    const result = validateTaskInput({ title: 'Buy milk', dueDate: '2025-12-31' });
    expect(result.valid).toBe(true);
  });

  it('should return error for missing title', () => {
    const result = validateTaskInput({ title: '', dueDate: null });
    expect(result.valid).toBe(false);
    expect(result.error).toMatch(/title/);
  });
});

