import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import fg from 'fast-glob';
import { readFileSafe, fileExists, isSecretName } from '../utils/security';
import type {
  RepositoryProfile,
  ConfigHealth,
  ConfigIssue,
  EnvVarInfo,
  PortMention,
  IssueSeverity,
  IssueCategory,
} from '../types';

// ─── Helpers ──────────────────────────────────────────────────────────────────

function issue(
  severity: IssueSeverity,
  confidence: number,
  category: IssueCategory,
  title: string,
  description: string,
  recommendedFix: string,
  extras: Partial<ConfigIssue> = {},
): ConfigIssue {
  return {
    id: uuidv4(),
    severity,
    confidence,
    category,
    title,
    description,
    evidence: [],
    recommendedFix,
    ...extras,
  };
}

// ─── ENV var analysis ─────────────────────────────────────────────────────────

const ENV_USAGE_RE = /process\.env\.([A-Z_][A-Z0-9_]*)/g;
const ENV_DEFINE_NAME_RE = /^([A-Z_][A-Z0-9_]*)(?:\s*=.*)?$/;

function parseEnvNames(content: string): string[] {
  return content
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#'))
    .map((l) => {
      const m = ENV_DEFINE_NAME_RE.exec(l);
